window.POEM_DATA={"poems":[{"id":"guan-ju","t":"关雎","d":"先秦","a":"佚名","f":"诗","pn":"洽川","rg":"陕西 · 渭南","lat":35.14,"lng":110.15,"l":["关关雎鸠，","在河之洲。","窈窕淑女，","君子好逑。","参差荇菜，","左右流之。","窈窕淑女，","寤寐求之。","求之不得，","寤寐思服。","悠哉悠哉，","辗转反侧。","参差荇菜，","左右采之。","窈窕淑女，","琴瑟友之。","参差荇菜，","左右芼之。","窈窕淑女，","钟鼓乐之。"],"g":["爱情","民歌"],"fm":[2,5]},{"id":"jian-jia","t":"蒹葭","d":"先秦","a":"佚名","f":"诗","pn":"渭水","rg":"陕西 · 宝鸡","lat":34.36,"lng":107.24,"l":["蒹葭苍苍，","白露为霜。","所谓伊人，","在水一方。","溯洄从之，","道阻且长。","溯游从之，","宛在水中央。","蒹葭萋萋，","白露未晞。","所谓伊人，","在水之湄。","溯洄从之，","道阻且跻。","溯游从之，","宛在水中坻。","蒹葭采采，","白露未已。","所谓伊人，","在水之涘。","溯洄从之，","道阻且右。","溯游从之，","宛在水中沚。"],"g":["爱情","相思"],"fm":[0,5]},{"id":"cai-wei","t":"采薇","d":"先秦","a":"佚名","f":"诗","pn":"泾水","rg":"甘肃 · 平凉","lat":35.54,"lng":106.68,"l":["采薇采薇，","薇亦作止。","曰归曰归，","岁亦莫止。","靡室靡家，","猃狁之故。","不遑启居，","猃狁之故。","采薇采薇，","薇亦柔止。","曰归曰归，","心亦忧止。","忧心烈烈，","载饥载渴。","我戍未定，","靡使归聘。","采薇采薇，","薇亦刚止。","曰归曰归，","岁亦阳止。","王事靡盬，","不遑启处。","忧心孔疚，","我行不来。","彼尔维何？","维常之华。","彼路斯何？","君子之车。","戎车既驾，","四牡业业。","岂敢定居？","一月三捷。","驾彼四牡，","四牡骙骙。","君子所依，","小人所腓。","四牡翼翼，","象弭鱼服。","岂不日戒？","猃狁孔棘。","昔我往矣，","杨柳依依。","今我来思，","雨雪霏霏。","行道迟迟，","载渴载饥。","我心伤悲，","莫知我哀！"],"g":["边塞","思乡"],"fm":[40,4]},{"id":"li-sao","t":"离骚（节选）","d":"先秦","a":"屈原","f":"诗","pn":"汨罗江","rg":"湖南 · 岳阳","lat":28.81,"lng":113.08,"l":["长太息以掩涕兮，","哀民生之多艰。","余虽好修姱以鞿羁兮，","謇朝谇而夕替。","既替余以蕙纕兮，","又申之以揽茝。","亦余心之所善兮，","虽九死其犹未悔。","怨灵修之浩荡兮，","终不察夫民心。","众女嫉余之蛾眉兮，","谣诼谓余以善淫。","固时俗之工巧兮，","偭规矩而改错。","背绳墨以追曲兮，","竞周容以为度。","忳郁邑余侘傺兮，","吾独穷困乎此时也。","宁溘死以流亡兮，","余不忍为此态也。","鸷鸟之不群兮，","自前世而固然。","何方圜之能周兮？","夫孰异道而相安？","屈心而抑志兮，","忍尤而攘诟。","伏清白以死直兮，","固前圣之所厚。"],"g":["言志","忧国"],"fm":[0,5]},{"id":"guo-shang","t":"国殇","d":"先秦","a":"屈原","f":"诗","pn":"秭归","rg":"湖北 · 宜昌","lat":30.83,"lng":110.98,"l":["操吴戈兮被犀甲，","车错毂兮短兵接。","旌蔽日兮敌若云，","矢交坠兮士争先。","凌余阵兮躐余行，","左骖殪兮右刃伤。","霾两轮兮絷四马，","援玉枹兮击鸣鼓。","天时坠兮威灵怒，","严杀尽兮弃原野。","出不入兮往不反，","平原忽兮路超远。","带长剑兮挟秦弓，","首身离兮心不惩。","诚既勇兮又以武，","终刚强兮不可凌。","身既死兮神以灵，","子魂魄兮为鬼雄。"],"g":["爱国","战争"],"fm":[16,3]},{"id":"guan-cang-hai","t":"观沧海","d":"汉","a":"曹操","f":"诗","pn":"碣石","rg":"河北 · 秦皇岛","lat":39.71,"lng":119.16,"l":["东临碣石，","以观沧海。","水何澹澹，","山岛竦峙。","树木丛生，","百草丰茂。","秋风萧瑟，","洪波涌起。","日月之行，","若出其中；","星汉灿烂，","若出其里。","幸甚至哉，","歌以咏志。"],"g":["山水","言志"],"fm":[8,4,4]},{"id":"duan-ge-xing","t":"短歌行","d":"汉","a":"曹操","f":"诗","pn":"邺城","rg":"河北 · 邯郸","lat":36.33,"lng":114.62,"l":["对酒当歌，","人生几何！","譬如朝露，","去日苦多。","慨当以慷，","忧思难忘。","何以解忧？","唯有杜康。","青青子衿，","悠悠我心。","但为君故，","沉吟至今。","呦呦鹿鸣，","食野之苹。","我有嘉宾，","鼓瑟吹笙。","明明如月，","何时可掇？","忧从中来，","不可断绝。","越陌度阡，","枉用相存。","契阔谈䜩，","心念旧恩。","月明星稀，","乌鹊南飞。","绕树三匝，","何枝可依？","山不厌高，","海不厌深。","周公吐哺，","天下归心。"],"g":["言志","感慨"],"fm":[0,5]},{"id":"tiao-tiao-qian-niu-xing","t":"迢迢牵牛星","d":"汉","a":"佚名","f":"诗","pn":"洛阳","rg":"河南 · 洛阳","lat":34.62,"lng":112.45,"l":["迢迢牵牛星，","皎皎河汉女。","纤纤擢素手，","札札弄机杼。","终日不成章，","泣涕零如雨。","河汉清且浅，","相去复几许？","盈盈一水间，","脉脉不得语。"],"g":["相思","爱情"],"fm":[8,4]},{"id":"shi-wu-cong-jun-zheng","t":"十五从军征","d":"汉","a":"佚名","f":"诗","pn":"上郡","rg":"陕西 · 榆林","lat":38.28,"lng":109.73,"l":["十五从军征，","八十始得归。","道逢乡里人：","家中有阿谁？","遥看是君家，","松柏冢累累。","兔从狗窦入，","雉从梁上飞。","中庭生旅谷，","井上生旅葵。","舂谷持作饭，","采葵持作羹。","羹饭一时熟，","不知贻阿谁。","出门东向看，","泪落沾我衣。"],"g":["民生","战争"],"fm":[0,3]},{"id":"jiang-nan","t":"江南","d":"汉","a":"佚名","f":"诗","pn":"太湖","rg":"江苏 · 苏州","lat":31.2,"lng":120.2,"l":["江南可采莲，","莲叶何田田。","鱼戏莲叶间。","鱼戏莲叶东，","鱼戏莲叶西，","鱼戏莲叶南，","鱼戏莲叶北。"],"g":["写景","民歌"],"fm":[0,4]},{"id":"da-feng-ge","t":"大风歌","d":"汉","a":"刘邦","f":"诗","pn":"沛县","rg":"江苏 · 徐州","lat":34.73,"lng":116.94,"l":["大风起兮云飞扬，","威加海内兮归故乡，","安得猛士兮守四方！"],"g":["言志","豪情"],"fm":[0,4,3]},{"id":"qiu-feng-ci","t":"秋风辞","d":"汉","a":"刘彻","f":"诗","pn":"汾阴后土祠","rg":"山西 · 运城","lat":35.42,"lng":110.83,"l":["秋风起兮白云飞，","草木黄落兮雁南归。","兰有秀兮菊有芳，","怀佳人兮不能忘。","泛楼船兮济汾河，","横中流兮扬素波。","箫鼓鸣兮发棹歌，","欢乐极兮哀情多。","少壮几时兮奈老何！"],"g":["感遇","悲秋"],"fm":[7,3]},{"id":"yin-jiu-qi-wu","t":"饮酒·其五","d":"魏晋","a":"陶渊明","f":"诗","pn":"柴桑","rg":"江西 · 九江","lat":29.4,"lng":115.85,"l":["结庐在人境，","而无车马喧。","问君何能尔？","心远地自偏。","采菊东篱下，","悠然见南山。","山气日夕佳，","飞鸟相与还。","此中有真意，","欲辨已忘言。"],"g":["隐逸","田园","哲理"],"fm":[4,5]},{"id":"yong-huai-qi-yi","t":"咏怀·其一","d":"魏晋","a":"阮籍","f":"诗","pn":"山阳竹林","rg":"河南 · 焦作","lat":35.42,"lng":113.4,"l":["夜中不能寐，","起坐弹鸣琴。","薄帷鉴明月，","清风吹我襟。","孤鸿号外野，","翔鸟鸣北林。","徘徊将何见？","忧思独伤心。"],"g":["感遇","愁思"],"fm":[0,3]},{"id":"qi-bu-shi","t":"七步诗","d":"魏晋","a":"曹植","f":"诗","pn":"洛阳宫","rg":"河南 · 洛阳","lat":34.72,"lng":112.62,"l":["煮豆持作羹，","漉菽以为汁。","萁在釜下然，","豆在釜中泣。","本自同根生，","相煎何太急？"],"g":["讽喻","亲情"],"fm":[4,5]},{"id":"chi-le-ge","t":"敕勒歌","d":"南北朝","a":"佚名","f":"诗","pn":"敕勒川","rg":"内蒙古 · 呼和浩特","lat":40.84,"lng":111.68,"l":["敕勒川，","阴山下。","天似穹庐，","笼盖四野。","天苍苍，","野茫茫，","风吹草低见牛羊。"],"g":["写景","民歌"],"fm":[5,5]},{"id":"wan-deng-san-shan","t":"晚登三山还望京邑","d":"南北朝","a":"谢朓","f":"诗","pn":"三山","rg":"江苏 · 南京","lat":31.88,"lng":118.68,"l":["灞涘望长安，","河阳视京县。","白日丽飞甍，","参差皆可见。","余霞散成绮，","澄江静如练。","喧鸟覆春洲，","杂英满芳甸。","去矣方滞淫，","怀哉罢欢宴。","佳期怅何许，","泪下如流霰。","有情知望乡，","谁能鬒不变？"],"g":["登临","思乡"],"fm":[4,3]},{"id":"deng-chi-shang-lou","t":"登池上楼","d":"南北朝","a":"谢灵运","f":"诗","pn":"始宁墅","rg":"浙江 · 绍兴","lat":29.98,"lng":120.85,"l":["潜虬媚幽姿，","飞鸿响远音。","薄霄愧云浮，","栖川怍渊沉。","进德智所拙，","退耕力不任。","徇禄反穷海，","卧疴对空林。","衾枕昧节候，","褰开暂窥临。","倾耳聆波澜，","举目眺岖嵚。","初景革绪风，","新阳改故阴。","池塘生春草，","园柳变鸣禽。","祁祁伤豳歌，","萋萋感楚吟。","索居易永久，","离群难处心。","持操岂独古，","无闷征在今。"],"g":["山水","隐逸","感遇"],"fm":[14,3]},{"id":"jing-ye-si","t":"静夜思","d":"唐","a":"李白","f":"诗","pn":"扬州旅舍","rg":"江苏 · 扬州","lat":32.39,"lng":119.42,"l":["床前明月光，","疑是地上霜。","举头望明月，","低头思故乡。"],"g":["思乡","月夜"],"fm":[2,5.5]},{"id":"wang-lushan-pubu","t":"望庐山瀑布","d":"唐","a":"李白","f":"诗","pn":"庐山香炉峰","rg":"江西 · 九江","lat":29.55,"lng":115.98,"l":["日照香炉生紫烟，","遥看瀑布挂前川。","飞流直下三千尺，","疑是银河落九天。"],"g":["山水","写景"],"fm":[2,5.5]},{"id":"zao-fa-bai-di-cheng","t":"早发白帝城","d":"唐","a":"李白","f":"诗","pn":"白帝城","rg":"重庆 · 奉节","lat":31.04,"lng":109.59,"l":["朝辞白帝彩云间，","千里江陵一日还。","两岸猿声啼不住，","轻舟已过万重山。"],"g":["行旅","山水"],"fm":[2,5.5]},{"id":"huang-he-lou-song","t":"黄鹤楼送孟浩然之广陵","d":"唐","a":"李白","f":"诗","pn":"黄鹤楼","rg":"湖北 · 武汉","lat":30.54,"lng":114.35,"l":["故人西辞黄鹤楼，","烟花三月下扬州。","孤帆远影碧空尽，","唯见长江天际流。"],"g":["赠别","登临"],"fm":[2,5.5]},{"id":"wang-tianmen-shan","t":"望天门山","d":"唐","a":"李白","f":"诗","pn":"天门山","rg":"安徽 · 马鞍山","lat":31.68,"lng":118.1,"l":["天门中断楚江开，","碧水东流至此回。","两岸青山相对出，","孤帆一片日边来。"],"g":["山水","行旅"],"fm":[2,4]},{"id":"du-zuo-jingting-shan","t":"独坐敬亭山","d":"唐","a":"李白","f":"诗","pn":"敬亭山","rg":"安徽 · 宣城","lat":30.95,"lng":118.75,"l":["众鸟高飞尽，","孤云独去闲。","相看两不厌，","只有敬亭山。"],"g":["山水","隐逸"],"fm":[2,4]},{"id":"zeng-wang-lun","t":"赠汪伦","d":"唐","a":"李白","f":"诗","pn":"桃花潭","rg":"安徽 · 泾县","lat":30.65,"lng":118.37,"l":["李白乘舟将欲行，","忽闻岸上踏歌声。","桃花潭水深千尺，","不及汪伦送我情。"],"g":["赠别","友情"],"fm":[2,5]},{"id":"du-jingmen-songbie","t":"渡荆门送别","d":"唐","a":"李白","f":"诗","pn":"荆门山","rg":"湖北 · 宜都","lat":30.78,"lng":111.3,"l":["渡远荆门外，","来从楚国游。","山随平野尽，","江入大荒流。","月下飞天镜，","云生结海楼。","仍怜故乡水，","万里送行舟。"],"g":["行旅","思乡"],"fm":[2,4]},{"id":"deng-jinling-fenghuang-tai","t":"登金陵凤凰台","d":"唐","a":"李白","f":"诗","pn":"凤凰台","rg":"江苏 · 南京","lat":32.01,"lng":118.78,"l":["凤凰台上凤凰游，","凤去台空江自流。","吴宫花草埋幽径，","晋代衣冠成古丘。","三山半落青天外，","二水中分白鹭洲。","总为浮云能蔽日，","长安不见使人愁。"],"g":["登临","怀古"],"fm":[4,4]},{"id":"mengyou-tianmu","t":"梦游天姥吟留别","d":"唐","a":"李白","f":"诗","pn":"天姥山","rg":"浙江 · 绍兴新昌","lat":29.15,"lng":121.02,"l":["海客谈瀛洲，","烟涛微茫信难求；","越人语天姥，","云霞明灭或可睹。","天姥连天向天横，","势拔五岳掩赤城。","天台四万八千丈，","对此欲倒东南倾。","我欲因之梦吴越，","一夜飞度镜湖月。","湖月照我影，","送我至剡溪。","谢公宿处今尚在，","渌水荡漾清猿啼。","脚著谢公屐，","身登青云梯。","半壁见海日，","空中闻天鸡。","千岩万转路不定，","迷花倚石忽已暝。","熊咆龙吟殷岩泉，","栗深林兮惊层巅。","云青青兮欲雨，","水澹澹兮生烟。","列缺霹雳，","丘峦崩摧。","洞天石扉，","訇然中开。","青冥浩荡不见底，","日月照耀金银台。","霓为衣兮风为马，","云之君兮纷纷而来下。","虎鼓瑟兮鸾回车，","仙之人兮列如麻。","忽魂悸以魄动，","恍惊起而长嗟。","惟觉时之枕席，","失向来之烟霞。","世间行乐亦如此，","古来万事东流水。","别君去兮何时还？","且放白鹿青崖间，","须行即骑访名山。","安能摧眉折腰事权贵，","使我不得开心颜！"],"g":["山水","隐逸"],"fm":[43,5]},{"id":"deng-guanque-lou","t":"登鹳雀楼","d":"唐","a":"王之涣","f":"诗","pn":"鹳雀楼","rg":"山西 · 运城永济","lat":34.85,"lng":110.33,"l":["白日依山尽，","黄河入海流。","欲穷千里目，","更上一层楼。"],"g":["登临","哲理"],"fm":[2,5.5]},{"id":"liangzhou-ci-wangzhihuan","t":"凉州词","d":"唐","a":"王之涣","f":"诗","pn":"凉州","rg":"甘肃 · 武威","lat":37.93,"lng":102.64,"l":["黄河远上白云间，","一片孤城万仞山。","羌笛何须怨杨柳，","春风不度玉门关。"],"g":["边塞","思乡"],"fm":[2,5.5]},{"id":"liangzhou-ci-wanghan","t":"凉州词","d":"唐","a":"王翰","f":"诗","pn":"凉州","rg":"甘肃 · 武威","lat":37.93,"lng":102.64,"l":["葡萄美酒夜光杯，","欲饮琵琶马上催。","醉卧沙场君莫笑，","古来征战几人回。"],"g":["边塞","豪情"],"fm":[2,5]},{"id":"huang-he-lou","t":"黄鹤楼","d":"唐","a":"崔颢","f":"诗","pn":"黄鹤楼","rg":"湖北 · 武汉","lat":30.54,"lng":114.35,"l":["昔人已乘黄鹤去，","此地空余黄鹤楼。","黄鹤一去不复返，","白云千载空悠悠。","晴川历历汉阳树，","芳草萋萋鹦鹉洲。","日暮乡关何处是？","烟波江上使人愁。"],"g":["登临","怀古","思乡"],"fm":[0,5.5]},{"id":"chu-sai","t":"出塞","d":"唐","a":"王昌龄","f":"诗","pn":"玉门关","rg":"甘肃 · 敦煌","lat":40.36,"lng":93.85,"l":["秦时明月汉时关，","万里长征人未还。","但使龙城飞将在，","不教胡马度阴山。"],"g":["边塞","爱国"],"fm":[2,5.5]},{"id":"furong-lou-song","t":"芙蓉楼送辛渐","d":"唐","a":"王昌龄","f":"诗","pn":"芙蓉楼","rg":"江苏 · 镇江","lat":32.2,"lng":119.45,"l":["寒雨连江夜入吴，","平明送客楚山孤。","洛阳亲友如相问，","一片冰心在玉壶。"],"g":["赠别","言志"],"fm":[2,5]},{"id":"cong-jun-xing","t":"从军行（其四）","d":"唐","a":"王昌龄","f":"诗","pn":"青海湖","rg":"青海 · 海北","lat":36.9,"lng":100.2,"l":["青海长云暗雪山，","孤城遥望玉门关。","黄沙百战穿金甲，","不破楼兰终不还。"],"g":["边塞","爱国"],"fm":[2,5]},{"id":"chun-xiao","t":"春晓","d":"唐","a":"孟浩然","f":"诗","pn":"鹿门山","rg":"湖北 · 襄阳","lat":31.98,"lng":112.2,"l":["春眠不觉晓，","处处闻啼鸟。","夜来风雨声，","花落知多少。"],"g":["写景","节令"],"fm":[0,5.5]},{"id":"su-jiangde-jiang","t":"宿建德江","d":"唐","a":"孟浩然","f":"诗","pn":"建德江","rg":"浙江 · 建德","lat":29.48,"lng":119.53,"l":["移舟泊烟渚，","日暮客愁新。","野旷天低树，","江清月近人。"],"g":["羁旅","写景"],"fm":[2,4]},{"id":"wang-dongting-zeng","t":"望洞庭湖赠张丞相","d":"唐","a":"孟浩然","f":"诗","pn":"洞庭湖","rg":"湖南 · 岳阳","lat":29.25,"lng":112.75,"l":["八月湖水平，","涵虚混太清。","气蒸云梦泽，","波撼岳阳城。","欲济无舟楫，","端居耻圣明。","坐观垂钓者，","徒有羡鱼情。"],"g":["山水","言志"],"fm":[2,4]},{"id":"guo-gu-ren-zhuang","t":"过故人庄","d":"唐","a":"孟浩然","f":"诗","pn":"襄阳故人庄","rg":"湖北 · 襄阳","lat":32.02,"lng":112.1,"l":["故人具鸡黍，","邀我至田家。","绿树村边合，","青山郭外斜。","开轩面场圃，","把酒话桑麻。","待到重阳日，","还来就菊花。"],"g":["田园","友情"],"fm":[2,4]},{"id":"hui-xiang-ou-shu","t":"回乡偶书","d":"唐","a":"贺知章","f":"诗","pn":"越州永兴","rg":"浙江 · 杭州","lat":30.16,"lng":120.25,"l":["少小离家老大回，","乡音无改鬓毛衰。","儿童相见不相识，","笑问客从何处来。"],"g":["思乡","感慨"],"fm":[2,5]},{"id":"ci-bei-gu-shan","t":"次北固山下","d":"唐","a":"王湾","f":"诗","pn":"北固山","rg":"江苏 · 镇江","lat":32.25,"lng":119.47,"l":["客路青山外，","行舟绿水前。","潮平两岸阔，","风正一帆悬。","海日生残夜，","江春入旧年。","乡书何处达？","归雁洛阳边。"],"g":["羁旅","写景","哲理"],"fm":[4,4]},{"id":"deng-youzhou-tai","t":"登幽州台歌","d":"唐","a":"陈子昂","f":"诗","pn":"幽州台","rg":"北京","lat":39.95,"lng":116.35,"l":["前不见古人，","后不见来者。","念天地之悠悠，","独怆然而涕下。"],"g":["登临","怀古","言志"],"fm":[2,5]},{"id":"wang-jimen","t":"望蓟门","d":"唐","a":"祖咏","f":"诗","pn":"蓟城","rg":"北京","lat":39.9,"lng":116.3,"l":["燕台一去客心惊，","笳鼓喧喧汉将营。","万里寒光生积雪，","三边曙色动危旌。","沙场烽火连胡月，","海畔云山拥蓟城。","少小虽非投笔吏，","论功还欲请长缨。"],"g":["边塞","言志"],"fm":[6,2]},{"id":"wang-yue","t":"望岳","d":"唐","a":"杜甫","f":"诗","pn":"泰山","rg":"山东 · 泰安","lat":36.25,"lng":117.1,"l":["岱宗夫如何？","齐鲁青未了。","造化钟神秀，","阴阳割昏晓。","荡胸生层云，","决眦入归鸟。","会当凌绝顶，","一览众山小。"],"g":["山水","登临","言志"],"fm":[6,5.5]},{"id":"chun-wang","t":"春望","d":"唐","a":"杜甫","f":"诗","pn":"长安","rg":"陕西 · 西安","lat":34.27,"lng":108.95,"l":["国破山河在，","城春草木深。","感时花溅泪，","恨别鸟惊心。","烽火连三月，","家书抵万金。","白头搔更短，","浑欲不胜簪。"],"g":["忧国","思乡"],"fm":[0,5.5]},{"id":"deng-gao","t":"登高","d":"唐","a":"杜甫","f":"诗","pn":"夔州白帝台","rg":"重庆 · 奉节","lat":31.05,"lng":109.58,"l":["风急天高猿啸哀，","渚清沙白鸟飞回。","无边落木萧萧下，","不尽长江滚滚来。","万里悲秋常作客，","百年多病独登台。","艰难苦恨繁霜鬓，","潦倒新停浊酒杯。"],"g":["登临","羁旅","悲秋"],"fm":[2,5.5]},{"id":"chun-ye-xi-yu","t":"春夜喜雨","d":"唐","a":"杜甫","f":"诗","pn":"成都草堂","rg":"四川 · 成都","lat":30.65,"lng":104.02,"l":["好雨知时节，","当春乃发生。","随风潜入夜，","润物细无声。","野径云俱黑，","江船火独明。","晓看红湿处，","花重锦官城。"],"g":["写景","咏物"],"fm":[2,5]},{"id":"mao-wu-ge","t":"茅屋为秋风所破歌","d":"唐","a":"杜甫","f":"诗","pn":"成都草堂","rg":"四川 · 成都","lat":30.65,"lng":104.02,"l":["八月秋高风怒号，","卷我屋上三重茅。","茅飞渡江洒江郊，","高者挂罥长林梢，","下者飘转沉塘坳。","南村群童欺我老无力，","忍能对面为盗贼。","公然抱茅入竹去，","唇焦口燥呼不得，","归来倚杖自叹息。","俄顷风定云墨色，","秋天漠漠向昏黑。","布衾多年冷似铁，","娇儿恶卧踏里裂。","床头屋漏无干处，","雨脚如麻未断绝。","自经丧乱少睡眠，","长夜沾湿何由彻！","安得广厦千万间，","大庇天下寒士俱欢颜，","风雨不动安如山！","呜呼！","何时眼前突兀见此屋，","吾庐独破受冻死亦足！"],"g":["民生","忧国"],"fm":[18,5,3]},{"id":"jueju-huangli","t":"绝句","d":"唐","a":"杜甫","f":"诗","pn":"成都浣花溪","rg":"四川 · 成都","lat":30.65,"lng":104.05,"l":["两个黄鹂鸣翠柳，","一行白鹭上青天。","窗含西岭千秋雪，","门泊东吴万里船。"],"g":["写景","田园"],"fm":[0,5]},{"id":"shu-xiang","t":"蜀相","d":"唐","a":"杜甫","f":"诗","pn":"武侯祠","rg":"四川 · 成都","lat":30.65,"lng":104.03,"l":["丞相祠堂何处寻？","锦官城外柏森森。","映阶碧草自春色，","隔叶黄鹂空好音。","三顾频烦天下计，","两朝开济老臣心。","出师未捷身先死，","长使英雄泪满襟。"],"g":["怀古","咏史"],"fm":[6,5]},{"id":"lv-ye-shu-huai","t":"旅夜书怀","d":"唐","a":"杜甫","f":"诗","pn":"忠州江舟","rg":"重庆 · 忠县","lat":30.3,"lng":108.04,"l":["细草微风岸，","危樯独夜舟。","星垂平野阔，","月涌大江流。","名岂文章著？","官应老病休。","飘飘何所似？","天地一沙鸥。"],"g":["羁旅","言志"],"fm":[2,4]},{"id":"deng-yueyang-lou","t":"登岳阳楼","d":"唐","a":"杜甫","f":"诗","pn":"岳阳楼","rg":"湖南 · 岳阳","lat":29.29,"lng":113.13,"l":["昔闻洞庭水，","今上岳阳楼。","吴楚东南坼，","乾坤日夜浮。","亲朋无一字，","老病有孤舟。","戎马关山北，","凭轩涕泗流。"],"g":["登临","忧国"],"fm":[2,4]},{"id":"jiangnan-feng","t":"江南逢李龟年","d":"唐","a":"杜甫","f":"诗","pn":"长沙湘江","rg":"湖南 · 长沙","lat":28.2,"lng":112.97,"l":["岐王宅里寻常见，","崔九堂前几度闻。","正是江南好风景，","落花时节又逢君。"],"g":["怀人","感慨"],"fm":[2,4]},{"id":"shanju-qiu-ming","t":"山居秋暝","d":"唐","a":"王维","f":"诗","pn":"辋川别业","rg":"陕西 · 西安蓝田","lat":34.05,"lng":109.3,"l":["空山新雨后，","天气晚来秋。","明月松间照，","清泉石上流。","竹喧归浣女，","莲动下渔舟。","随意春芳歇，","王孙自可留。"],"g":["山水","隐逸"],"fm":[2,5.5]},{"id":"song-yuan-er","t":"送元二使安西","d":"唐","a":"王维","f":"诗","pn":"渭城","rg":"陕西 · 咸阳","lat":34.33,"lng":108.7,"l":["渭城朝雨浥轻尘，","客舍青青柳色新。","劝君更尽一杯酒，","西出阳关无故人。"],"g":["赠别","边塞"],"fm":[2,5.5]},{"id":"jiuyue-jiu","t":"九月九日忆山东兄弟","d":"唐","a":"王维","f":"诗","pn":"蒲州","rg":"山西 · 运城永济","lat":34.85,"lng":110.33,"l":["独在异乡为异客，","每逢佳节倍思亲。","遥知兄弟登高处，","遍插茱萸少一人。"],"g":["思乡","节令"],"fm":[0,5.5]},{"id":"shi-zhi-sai","t":"使至塞上","d":"唐","a":"王维","f":"诗","pn":"萧关","rg":"宁夏 · 吴忠同心","lat":36.6,"lng":106.7,"l":["单车欲问边，","属国过居延。","征蓬出汉塞，","归雁入胡天。","大漠孤烟直，","长河落日圆。","萧关逢候骑，","都护在燕然。"],"g":["边塞","行旅"],"fm":[4,5.5]},{"id":"zhongnan-shan","t":"终南山","d":"唐","a":"王维","f":"诗","pn":"终南山","rg":"陕西 · 西安","lat":33.95,"lng":108.9,"l":["太乙近天都，","连山接海隅。","白云回望合，","青霭入看无。","分野中峰变，","阴晴众壑殊。","欲投人处宿，","隔水问樵夫。"],"g":["山水","隐逸"],"fm":[2,3]},{"id":"chuzhou-xi-jian","t":"滁州西涧","d":"唐","a":"韦应物","f":"诗","pn":"滁州西涧","rg":"安徽 · 滁州","lat":32.3,"lng":118.32,"l":["独怜幽草涧边生，","上有黄鹂深树鸣。","春潮带雨晚来急，","野渡无人舟自横。"],"g":["山水","隐逸"],"fm":[2,4]},{"id":"fengqiao-ye-bo","t":"枫桥夜泊","d":"唐","a":"张继","f":"诗","pn":"枫桥","rg":"江苏 · 苏州","lat":31.31,"lng":120.56,"l":["月落乌啼霜满天，","江枫渔火对愁眠。","姑苏城外寒山寺，","夜半钟声到客船。"],"g":["羁旅","愁思"],"fm":[2,5.5]},{"id":"wuyi-xiang","t":"乌衣巷","d":"唐","a":"刘禹锡","f":"诗","pn":"乌衣巷","rg":"江苏 · 南京","lat":32.02,"lng":118.78,"l":["朱雀桥边野草花，","乌衣巷口夕阳斜。","旧时王谢堂前燕，","飞入寻常百姓家。"],"g":["怀古","咏史"],"fm":[2,5]},{"id":"zhuzhi-ci","t":"竹枝词（其一）","d":"唐","a":"刘禹锡","f":"诗","pn":"夔州","rg":"重庆 · 奉节","lat":31.05,"lng":109.58,"l":["杨柳青青江水平，","闻郎江上踏歌声。","东边日出西边雨，","道是无晴却有晴。"],"g":["爱情","民歌"],"fm":[2,4]},{"id":"wang-dongting","t":"望洞庭","d":"唐","a":"刘禹锡","f":"诗","pn":"洞庭湖","rg":"湖南 · 岳阳","lat":29.25,"lng":112.75,"l":["湖光秋月两相和，","潭面无风镜未磨。","遥望洞庭山水翠，","白银盘里一青螺。"],"g":["山水","写景"],"fm":[2,4]},{"id":"chou-yangzhou","t":"酬乐天扬州初逢席上见赠","d":"唐","a":"刘禹锡","f":"诗","pn":"扬州","rg":"江苏 · 扬州","lat":32.39,"lng":119.42,"l":["巴山楚水凄凉地，","二十三年弃置身。","怀旧空吟闻笛赋，","到乡翻似烂柯人。","沉舟侧畔千帆过，","病树前头万木春。","今日听君歌一曲，","暂凭杯酒长精神。"],"g":["酬赠","言志"],"fm":[4,5]},{"id":"bo-qinhuai","t":"泊秦淮","d":"唐","a":"杜牧","f":"诗","pn":"秦淮河","rg":"江苏 · 南京","lat":32.02,"lng":118.78,"l":["烟笼寒水月笼沙，","夜泊秦淮近酒家。","商女不知亡国恨，","隔江犹唱后庭花。"],"g":["怀古","忧国"],"fm":[2,5]},{"id":"jiangnan-chun","t":"江南春","d":"唐","a":"杜牧","f":"诗","pn":"江南","rg":"浙江 · 嘉兴","lat":30.75,"lng":120.75,"l":["千里莺啼绿映红，","水村山郭酒旗风。","南朝四百八十寺，","多少楼台烟雨中。"],"g":["写景","怀古"],"fm":[2,5]},{"id":"qing-ming","t":"清明","d":"唐","a":"杜牧","f":"诗","pn":"杏花村","rg":"安徽 · 池州","lat":30.65,"lng":117.48,"l":["清明时节雨纷纷，","路上行人欲断魂。","借问酒家何处有？","牧童遥指杏花村。"],"g":["节令","行旅"],"fm":[0,5.5]},{"id":"chi-bi","t":"赤壁","d":"唐","a":"杜牧","f":"诗","pn":"黄州赤壁","rg":"湖北 · 黄冈","lat":30.45,"lng":114.88,"l":["折戟沉沙铁未销，","自将磨洗认前朝。","东风不与周郎便，","铜雀春深锁二乔。"],"g":["怀古","咏史"],"fm":[2,4]},{"id":"guo-huaqing-gong","t":"过华清宫","d":"唐","a":"杜牧","f":"诗","pn":"华清宫","rg":"陕西 · 西安临潼","lat":34.37,"lng":109.22,"l":["长安回望绣成堆，","山顶千门次第开。","一骑红尘妃子笑，","无人知是荔枝来。"],"g":["咏史","讽喻"],"fm":[2,4]},{"id":"jin-se","t":"锦瑟","d":"唐","a":"李商隐","f":"诗","pn":"长安","rg":"陕西 · 西安","lat":34.27,"lng":108.95,"l":["锦瑟无端五十弦，","一弦一柱思华年。","庄生晓梦迷蝴蝶，","望帝春心托杜鹃。","沧海月明珠有泪，","蓝田日暖玉生烟。","此情可待成追忆？","只是当时已惘然。"],"g":["追忆","爱情"],"fm":[6,5.5]},{"id":"ye-yu-ji-bei","t":"夜雨寄北","d":"唐","a":"李商隐","f":"诗","pn":"巴山","rg":"重庆","lat":29.56,"lng":106.55,"l":["君问归期未有期，","巴山夜雨涨秋池。","何当共剪西窗烛，","却话巴山夜雨时。"],"g":["怀人","羁旅"],"fm":[2,5.5]},{"id":"ti-ducheng-nanzhuang","t":"题都城南庄","d":"唐","a":"崔护","f":"诗","pn":"长安城南","rg":"陕西 · 西安","lat":34.2,"lng":108.95,"l":["去年今日此门中，","人面桃花相映红。","人面不知何处去？","桃花依旧笑春风。"],"g":["爱情","怅惘"],"fm":[2,5]},{"id":"jiang-xue","t":"江雪","d":"唐","a":"柳宗元","f":"诗","pn":"永州","rg":"湖南 · 永州","lat":26.43,"lng":111.6,"l":["千山鸟飞绝，","万径人踪灭。","孤舟蓑笠翁，","独钓寒江雪。"],"g":["山水","隐逸","孤傲"],"fm":[2,5.5]},{"id":"pipa-xing","t":"琵琶行","d":"唐","a":"白居易","f":"诗","pn":"浔阳江","rg":"江西 · 九江","lat":29.7,"lng":116,"l":["浔阳江头夜送客，","枫叶荻花秋瑟瑟。","主人下马客在船，","举酒欲饮无管弦。","醉不成欢惨将别，","别时茫茫江浸月。","忽闻水上琵琶声，","主人忘归客不发。","寻声暗问弹者谁？","琵琶声停欲语迟。","移船相近邀相见，","添酒回灯重开宴。","千呼万唤始出来，","犹抱琵琶半遮面。","转轴拨弦三两声，","未成曲调先有情。","弦弦掩抑声声思，","似诉平生不得志。","低眉信手续续弹，","说尽心中无限事。","轻拢慢捻抹复挑，","初为《霓裳》后《六幺》。","大弦嘈嘈如急雨，","小弦切切如私语。","嘈嘈切切错杂弹，","大珠小珠落玉盘。","间关莺语花底滑，","幽咽泉流冰下难。","冰泉冷涩弦凝绝，","凝绝不通声暂歇。","别有幽愁暗恨生，","此时无声胜有声。","银瓶乍破水浆迸，","铁骑突出刀枪鸣。","曲终收拨当心画，","四弦一声如裂帛。","东船西舫悄无言，","唯见江心秋月白。","沉吟放拨插弦中，","整顿衣裳起敛容。","自言本是京城女，","家在虾蟆陵下住。","十三学得琵琶成，","名属教坊第一部。","曲罢曾教善才服，","妆成每被秋娘妒。","五陵年少争缠头，","一曲红绡不知数。","钿头银篦击节碎，","血色罗裙翻酒污。","今年欢笑复明年，","秋月春风等闲度。","弟走从军阿姨死，","暮去朝来颜色故。","门前冷落鞍马稀，","老大嫁作商人妇。","商人重利轻别离，","前月浮梁买茶去。","去来江口守空船，","绕船月明江水寒。","夜深忽梦少年事，","梦啼妆泪红阑干。","我闻琵琶已叹息，","又闻此语重唧唧。","同是天涯沦落人，","相逢何必曾相识！","我从去年辞帝京，","谪居卧病浔阳城。","浔阳地僻无音乐，","终岁不闻丝竹声。","住近湓江地低湿，","黄芦苦竹绕宅生。","其间旦暮闻何物？","杜鹃啼血猿哀鸣。","春江花朝秋月夜，","往往取酒还独倾。","岂无山歌与村笛？","呕哑嘲哳难为听。","今夜闻君琵琶语，","如听仙乐耳暂明。","莫辞更坐弹一曲，","为君翻作《琵琶行》。","感我此言良久立，","却坐促弦弦转急。","凄凄不似向前声，","满座重闻皆掩泣。","座中泣下谁最多？","江州司马青衫湿。"],"pr":"元和十年，予左迁九江郡司马。明年秋，送客湓浦口，闻舟中夜弹琵琶者。听其音，铮铮然有京都声。问其人，本长安倡女，尝学琵琶于穆、曹二善才，年长色衰，委身为贾人妇。遂命酒，使快弹数曲。曲罢悯然，自叙少小时欢乐事，今漂沦憔悴，转徙于江湖间。予出官二年，恬然自安，感斯人言，是夕始觉有迁谪意。因为长句，歌以赠之，凡六百一十六言，命曰《琵琶行》。","g":["音乐","感遇"],"fm":[64,5]},{"id":"qiantang-hu","t":"钱塘湖春行","d":"唐","a":"白居易","f":"诗","pn":"西湖","rg":"浙江 · 杭州","lat":30.25,"lng":120.15,"l":["孤山寺北贾亭西，","水面初平云脚低。","几处早莺争暖树，","谁家新燕啄春泥。","乱花渐欲迷人眼，","浅草才能没马蹄。","最爱湖东行不足，","绿杨阴里白沙堤。"],"g":["写景","行旅"],"fm":[4,4]},{"id":"yi-jiangnan","t":"忆江南","d":"唐","a":"白居易","f":"词","pn":"杭州","rg":"浙江 · 杭州","lat":30.25,"lng":120.15,"l":["江南好，","风景旧曾谙。","日出江花红胜火，","春来江水绿如蓝。","能不忆江南？"],"g":["怀旧","写景"],"fm":[2,5]},{"id":"fu-de-gu-yuan-cao","t":"赋得古原草送别","d":"唐","a":"白居易","f":"诗","pn":"长安","rg":"陕西 · 西安","lat":34.27,"lng":108.95,"l":["离离原上草，","一岁一枯荣。","野火烧不尽，","春风吹又生。","远芳侵古道，","晴翠接荒城。","又送王孙去，","萋萋满别情。"],"g":["赠别","咏物"],"fm":[2,5.5]},{"id":"ti-po-shan-si","t":"题破山寺后禅院","d":"唐","a":"常建","f":"诗","pn":"破山寺","rg":"江苏 · 苏州常熟","lat":31.72,"lng":120.74,"l":["清晨入古寺，","初日照高林。","曲径通幽处，","禅房花木深。","山光悦鸟性，","潭影空人心。","万籁此都寂，","但余钟磬音。"],"g":["山水","禅意"],"fm":[2,4]},{"id":"ye-wang","t":"野望","d":"唐","a":"王绩","f":"诗","pn":"东皋","rg":"山西 · 运城河津","lat":35.6,"lng":110.7,"l":["东皋薄暮望，","徙倚欲何依。","树树皆秋色，","山山唯落晖。","牧人驱犊返，","猎马带禽归。","相顾无相识，","长歌怀采薇。"],"g":["田园","隐逸"],"fm":[2,3]},{"id":"song-ling-che","t":"送灵澈上人","d":"唐","a":"刘长卿","f":"诗","pn":"竹林寺","rg":"江苏 · 镇江","lat":32.2,"lng":119.45,"l":["苍苍竹林寺，","杳杳钟声晚。","荷笠带斜阳，","青山独归远。"],"g":["赠别","禅意"],"fm":[2,3]},{"id":"baixue-ge","t":"白雪歌送武判官归京","d":"唐","a":"岑参","f":"诗","pn":"轮台","rg":"新疆 · 乌鲁木齐","lat":43.8,"lng":87.6,"l":["北风卷地白草折，","胡天八月即飞雪。","忽如一夜春风来，","千树万树梨花开。","散入珠帘湿罗幕，","狐裘不暖锦衾薄。","将军角弓不得控，","都护铁衣冷难着。","瀚海阑干百丈冰，","愁云惨淡万里凝。","中军置酒饮归客，","胡琴琵琶与羌笛。","纷纷暮雪下辕门，","风掣红旗冻不翻。","轮台东门送君去，","去时雪满天山路。","山回路转不见君，","雪上空留马行处。"],"g":["边塞","赠别"],"fm":[2,5]},{"id":"lan-xi-zhao-ge","t":"兰溪棹歌","d":"唐","a":"戴叔伦","f":"诗","pn":"兰溪","rg":"浙江 · 金华兰溪","lat":29.2,"lng":119.47,"l":["凉月如眉挂柳湾，","越中山色镜中看。","兰溪三日桃花雨，","半夜鲤鱼来上滩。"],"g":["写景","民歌"],"fm":[2,2]},{"id":"shangshan-zao-xing","t":"商山早行","d":"唐","a":"温庭筠","f":"诗","pn":"商山","rg":"陕西 · 商洛","lat":33.85,"lng":109.9,"l":["晨起动征铎，","客行悲故乡。","鸡声茅店月，","人迹板桥霜。","槲叶落山路，","枳花明驿墙。","因思杜陵梦，","凫雁满回塘。"],"g":["羁旅","思乡"],"fm":[2,4]},{"id":"han-shi","t":"寒食","d":"唐","a":"韩翃","f":"诗","pn":"长安","rg":"陕西 · 西安","lat":34.27,"lng":108.95,"l":["春城无处不飞花，","寒食东风御柳斜。","日暮汉宫传蜡烛，","轻烟散入五侯家。"],"g":["节令","讽喻"],"fm":[0,4]},{"id":"xing-lu-nan","t":"行路难·其一","d":"唐","a":"李白","f":"诗","pn":"长安","rg":"陕西 · 西安","lat":34.28,"lng":108.95,"l":["金樽清酒斗十千，","玉盘珍羞直万钱。","停杯投箸不能食，","拔剑四顾心茫然。","欲渡黄河冰塞川，","将登太行雪满山。","闲来垂钓碧溪上，","忽复乘舟梦日边。","行路难，行路难，","多歧路，今安在？","长风破浪会有时，","直挂云帆济沧海。"],"g":["言志","豪情"],"fm":[10,5]},{"id":"song-du-shaofu","t":"送杜少府之任蜀州","d":"唐","a":"王勃","f":"诗","pn":"长安","rg":"陕西 · 西安","lat":34.28,"lng":108.95,"l":["城阙辅三秦，","风烟望五津。","与君离别意，","同是宦游人。","海内存知己，","天涯若比邻。","无为在歧路，","儿女共沾巾。"],"g":["赠别","友情"],"fm":[4,5]},{"id":"chun-jiang-hua-yue-ye","t":"春江花月夜","d":"唐","a":"张若虚","f":"诗","pn":"扬州","rg":"江苏 · 扬州","lat":32.39,"lng":119.42,"l":["春江潮水连海平，","海上明月共潮生。","滟滟随波千万里，","何处春江无月明！","江流宛转绕芳甸，","月照花林皆似霰。","空里流霜不觉飞，","汀上白沙看不见。","江天一色无纤尘，","皎皎空中孤月轮。","江畔何人初见月？","江月何年初照人？","人生代代无穷已，","江月年年只相似。","不知江月待何人，","但见长江送流水。","白云一片去悠悠，","青枫浦上不胜愁。","谁家今夜扁舟子？","何处相思明月楼？","可怜楼上月徘徊，","应照离人妆镜台。","玉户帘中卷不去，","捣衣砧上拂还来。","此时相望不相闻，","愿逐月华流照君。","鸿雁长飞光不度，","鱼龙潜跃水成文。","昨夜闲潭梦落花，","可怜春半不还家。","江水流春去欲尽，","江潭落月复西斜。","斜月沉沉藏海雾，","碣石潇湘无限路。","不知乘月几人归，","落月摇情满江树。"],"g":["写景","月夜","羁旅"],"fm":[0,5.5]},{"id":"lu-zhai","t":"鹿柴","d":"唐","a":"王维","f":"诗","pn":"辋川别业","rg":"陕西 · 西安蓝田","lat":34.05,"lng":109.3,"l":["空山不见人，","但闻人语响。","返景入深林，","复照青苔上。"],"g":["山水","禅意"],"fm":[0,4]},{"id":"han-jiang-lin-fan","t":"汉江临泛","d":"唐","a":"王维","f":"诗","pn":"襄阳","rg":"湖北 · 襄阳","lat":32.02,"lng":112.1,"l":["楚塞三湘接，","荆门九派通。","江流天地外，","山色有无中。","郡邑浮前浦，","波澜动远空。","襄阳好风日，","留醉与山翁。"],"g":["山水","写景"],"fm":[2,4]},{"id":"du-han-jiang","t":"渡汉江","d":"唐","a":"宋之问","f":"诗","pn":"襄阳","rg":"湖北 · 襄阳","lat":32.02,"lng":112.1,"l":["岭外音书断，","经冬复历春。","近乡情更怯，","不敢问来人。"],"g":["思乡","羁旅"],"fm":[2,4]},{"id":"wang-yue-huai-yuan","t":"望月怀远","d":"唐","a":"张九龄","f":"诗","pn":"荆州","rg":"湖北 · 荆州","lat":30.35,"lng":112.19,"l":["海上生明月，","天涯共此时。","情人怨遥夜，","竟夕起相思。","灭烛怜光满，","披衣觉露滋。","不堪盈手赠，","还寝梦佳期。"],"g":["月夜","相思"],"fm":[0,5]},{"id":"zao-chun-zhang-shui-bu","t":"早春呈水部张十八员外","d":"唐","a":"韩愈","f":"诗","pn":"长安","rg":"陕西 · 西安","lat":34.28,"lng":108.95,"l":["天街小雨润如酥，","草色遥看近却无。","最是一年春好处，","绝胜烟柳满皇都。"],"g":["写景","节令"],"fm":[0,5]},{"id":"bie-dong-da","t":"别董大","d":"唐","a":"高适","f":"诗","pn":"睢阳","rg":"河南 · 商丘","lat":34.39,"lng":115.65,"l":["千里黄云白日曛，","北风吹雁雪纷纷。","莫愁前路无知己，","天下谁人不识君。"],"g":["赠别","边塞"],"fm":[2,5]},{"id":"yue-ye-yi-she-di","t":"月夜忆舍弟","d":"唐","a":"杜甫","f":"诗","pn":"秦州","rg":"甘肃 · 天水","lat":34.58,"lng":105.72,"l":["戍鼓断人行，","边秋一雁声。","露从今夜白，","月是故乡明。","有弟皆分散，","无家问死生。","寄书长不达，","况乃未休兵。"],"g":["思乡","月夜"],"fm":[2,5]},{"id":"qiu-pu-ge","t":"秋浦歌（其十五）","d":"唐","a":"李白","f":"诗","pn":"秋浦","rg":"安徽 · 池州","lat":30.66,"lng":117.49,"l":["白发三千丈，","缘愁似个长。","不知明镜里，","何处得秋霜。"],"g":["感遇","愁思"],"fm":[0,4]},{"id":"xuanzhou-xietiao-lou","t":"宣州谢朓楼饯别校书叔云","d":"唐","a":"李白","f":"诗","pn":"宣州","rg":"安徽 · 宣城","lat":30.95,"lng":118.76,"l":["弃我去者，","昨日之日不可留；","乱我心者，","今日之日多烦忧。","长风万里送秋雁，","对此可以酣高楼。","蓬莱文章建安骨，","中间小谢又清发。","俱怀逸兴壮思飞，","欲上青天揽明月。","抽刀断水水更流，","举杯销愁愁更愁。","人生在世不称意，","明朝散发弄扁舟。"],"g":["登临","感遇"],"fm":[10,5]},{"id":"you-zi-yin","t":"游子吟","d":"唐","a":"孟郊","f":"诗","pn":"溧阳","rg":"江苏 · 常州","lat":31.42,"lng":119.48,"l":["慈母手中线，","游子身上衣。","临行密密缝，","意恐迟迟归。","谁言寸草心，","报得三春晖。"],"g":["亲情","母爱"],"fm":[4,5.5]},{"id":"deng-ke-hou","t":"登科后","d":"唐","a":"孟郊","f":"诗","pn":"长安","rg":"陕西 · 西安","lat":34.28,"lng":108.95,"l":["昔日龌龊不足夸，","今朝放荡思无涯。","春风得意马蹄疾，","一日看尽长安花。"],"g":["科举","快意"],"fm":[2,5]},{"id":"yanmen-taishou-xing","t":"雁门太守行","d":"唐","a":"李贺","f":"诗","pn":"雁门关","rg":"山西 · 忻州代县","lat":39.17,"lng":112.86,"l":["黑云压城城欲摧，","甲光向日金鳞开。","角声满天秋色里，","塞上燕脂凝夜紫。","半卷红旗临易水，","霜重鼓寒声不起。","报君黄金台上意，","提携玉龙为君死。"],"g":["边塞","战争"],"fm":[0,4]},{"id":"ye-shang-shou-jiang-cheng","t":"夜上受降城闻笛","d":"唐","a":"李益","f":"诗","pn":"受降城","rg":"内蒙古 · 呼和浩特","lat":40.28,"lng":111.13,"l":["回乐烽前沙似雪，","受降城外月如霜。","不知何处吹芦管，","一夜征人尽望乡。"],"g":["边塞","思乡"],"fm":[2,4]},{"id":"zhong-nan-wang-yu-xue","t":"终南望余雪","d":"唐","a":"祖咏","f":"诗","pn":"终南山","rg":"陕西 · 西安","lat":33.95,"lng":108.9,"l":["终南阴岭秀，","积雪浮云端。","林表明霁色，","城中增暮寒。"],"g":["写景","冬雪"],"fm":[2,3]},{"id":"tao-hua-xi","t":"桃花溪","d":"唐","a":"张旭","f":"诗","pn":"桃花溪","rg":"湖南 · 常德","lat":29.04,"lng":111.68,"l":["隐隐飞桥隔野烟，","石矶西畔问渔船。","桃花尽日随流水，","洞在清溪何处边？"],"g":["山水","怀古"],"fm":[2,3]},{"id":"chun-han-ying","t":"春寒影夜泊","d":"唐","a":"张旭","f":"诗","pn":"吴中","rg":"江苏 · 苏州","lat":31.3,"lng":120.62,"l":["春日色里春寒浅，","薄暮钟声隔水闻。","一夜东风吹柳绿，","满城花信启春心。"],"g":["写景","节令"],"fm":[2,1]},{"id":"shan-ming-niao-ti","t":"山中道士","d":"唐","a":"贾岛","f":"诗","pn":"终南山","rg":"陕西 · 西安","lat":33.95,"lng":108.9,"l":["松下问童子，","言师采药去。","只在此山中，","云深不知处。"],"g":["访隐","禅意"],"fm":[2,5]},{"id":"wang-yue-tang","t":"题稚子弄冰","d":"唐","a":"韩偓","f":"诗","pn":"长安郊野","rg":"陕西 · 西安","lat":34.2,"lng":108.88,"l":["稚子金盆脱晓冰，","彩丝穿取当银钲。","敲成玉磬穿林响，","忽作玻璃碎地声。"],"g":["童趣","写景"],"fm":[2,3]},{"id":"zhongqiu-yue","t":"中秋月","d":"唐","a":"李商隐","f":"诗","pn":"长安","rg":"陕西 · 西安","lat":34.27,"lng":108.88,"l":["初闻征雁已无蝉，","百尺楼高水接天。","青女素娥俱耐冷，","月中霜里斗婵娟。"],"g":["月夜","节令"],"fm":[2,3]},{"id":"wang-dongting-lu-mengtong","t":"宿洞庭","d":"唐","a":"李商隐","f":"诗","pn":"洞庭湖","rg":"湖南 · 岳阳","lat":29.25,"lng":112.75,"l":["客散青天月，","山空碧海潮。","不知何所入，","一夜听风潮。"],"g":["羁旅","写景"],"fm":[0,1]},{"id":"feng-qiao-jin-ye-liang","t":"题寒山寺","d":"唐","a":"张继","f":"诗","pn":"苏州寒山寺","rg":"江苏 · 苏州","lat":31.32,"lng":120.57,"l":["姑苏城外寒山寺，","夜半钟声到客船。","江枫渔火成诗句，","惆怅千年仍客眠。"],"g":["羁旅","月夜"],"fm":[0,1]},{"id":"jiang-shang-weng","t":"江上渔者","d":"唐","a":"杜荀鹤","f":"诗","pn":"吴越水乡","rg":"江苏 · 苏州","lat":31.29,"lng":120.58,"l":["江上往来人，","但爱鲈鱼美。","君看一叶舟，","出没风波里。"],"g":["民生","写景"],"fm":[2,4]},{"id":"wei-chuan-tian-jia","t":"渭川田家","d":"唐","a":"王维","f":"诗","pn":"渭川","rg":"陕西 · 咸阳","lat":34.33,"lng":108.71,"l":["斜光照墟落，","穷巷牛羊归。","野老念牧童，","倚杖候荆扉。","雉雊麦苗秀，","蚕眠桑叶稀。","田夫荷锄至，","相见语依依。","即此羡闲逸，","怅然吟式微。"],"g":["田园","闲适","隐逸"],"fm":[0,3]},{"id":"sai-xia-qu-lintao","t":"塞下曲","d":"唐","a":"王昌龄","f":"诗","pn":"临洮","rg":"甘肃 · 定西","lat":34.43,"lng":104.04,"l":["饮马渡秋水，","水寒风似刀。","平沙日未没，","黯黯见临洮。","昔日长城战，","咸言意气高。","黄尘足今古，","白骨乱蓬蒿。"],"g":["边塞","战争","感怀"],"fm":[0,3]},{"id":"feng-ru-jing-shi","t":"逢入京使","d":"唐","a":"岑参","f":"诗","pn":"安西都护府","rg":"新疆 · 阿克苏","lat":41.17,"lng":80.26,"l":["故园东望路漫漫，","双袖龙钟泪不干。","马上相逢无纸笔，","凭君传语报平安。"],"g":["边塞","思乡","行旅"],"fm":[2,4]},{"id":"ying-zhou-ge","t":"营州歌","d":"唐","a":"高适","f":"诗","pn":"营州","rg":"辽宁 · 朝阳","lat":41.58,"lng":120.45,"l":["营州少年厌原野，","狐裘蒙茸猎城下。","虏酒千钟不醉人，","胡儿十岁能骑马。"],"g":["边塞","豪情","写景"],"fm":[2,2]},{"id":"gu-cong-jun-xing","t":"古从军行","d":"唐","a":"李颀","f":"诗","pn":"交河","rg":"新疆 · 吐鲁番","lat":42.95,"lng":89.19,"l":["白日登山望烽火，","黄昏饮马傍交河。","行人刁斗风沙暗，","公主琵琶幽怨多。","野云万里无城郭，","雨雪纷纷连大漠。","胡雁哀鸣夜夜飞，","胡儿眼泪双双落。","闻道玉门犹被遮，","应将性命逐轻车。","年年战骨埋荒外，","空见蒲桃入汉家。"],"g":["边塞","战争","讽喻"],"fm":[10,3]},{"id":"xing-jing-hua-yin","t":"行经华阴","d":"唐","a":"崔颢","f":"诗","pn":"华山","rg":"陕西 · 渭南","lat":34.48,"lng":110.09,"l":["岧峣太华俯咸京，","天外三峰削不成。","武帝祠前云欲散，","仙人掌上雨初晴。","河山北枕秦关险，","驿路西连汉畤平。","借问路傍名利客，","何如此处学长生。"],"g":["山水","登临","感怀"],"fm":[0,2]},{"id":"chun-fan-ruoye-xi","t":"春泛若耶溪","d":"唐","a":"綦毋潜","f":"诗","pn":"若耶溪","rg":"浙江 · 绍兴","lat":29.95,"lng":120.6,"l":["幽意无断绝，","此去随所偶。","晚风吹行舟，","花路入溪口。","际夜转西壑，","隔山望南斗。","潭烟飞溶溶，","林月低向后。","生事且弥漫，","愿为持竿叟。"],"g":["山水","隐逸","写景"],"fm":[6,2]},{"id":"huai-shang-xi-hui","t":"淮上喜会梁州故人","d":"唐","a":"韦应物","f":"诗","pn":"淮上","rg":"江苏 · 淮安","lat":33.55,"lng":119.02,"l":["江汉曾为客，","相逢每醉还。","浮云一别后，","流水十年间。","欢笑情如旧，","萧疏鬓已斑。","何因不归去，","淮上有秋山。"],"g":["赠别","怀旧","感慨"],"fm":[2,3]},{"id":"cong-jun-bei-zheng","t":"从军北征","d":"唐","a":"李益","f":"诗","pn":"天山","rg":"新疆 · 乌鲁木齐","lat":43.83,"lng":87.62,"l":["天山雪后海风寒，","横笛偏吹行路难。","碛里征人三十万，","一时回首月中看。"],"g":["边塞","思乡","月夜"],"fm":[2,2]},{"id":"sai-xia-qu-yue-hei","t":"塞下曲","d":"唐","a":"卢纶","f":"诗","pn":"阴山","rg":"内蒙古 · 包头","lat":41.2,"lng":110,"l":["月黑雁飞高，","单于夜遁逃。","欲将轻骑逐，","大雪满弓刀。"],"g":["边塞","战争","豪情"],"fm":[2,4]},{"id":"qiu-si-luoyang","t":"秋思","d":"唐","a":"张籍","f":"诗","pn":"洛阳","rg":"河南 · 洛阳","lat":34.62,"lng":112.45,"l":["洛阳城里见秋风，","欲作家书意万重。","复恐匆匆说不尽，","行人临发又开封。"],"g":["思乡","羁旅","愁思"],"fm":[2,4]},{"id":"ti-dizhi-shutang","t":"题弟侄书堂","d":"唐","a":"杜荀鹤","f":"诗","pn":"九华山","rg":"安徽 · 池州","lat":30.48,"lng":117.81,"l":["何事居穷道不穷，","乱时还与静时同。","家山虽在干戈地，","弟侄常修礼乐风。","窗竹影摇书案上，","野泉声入砚池中。","少年辛苦终身事，","莫向光阴惰寸功。"],"g":["励志","言志","读书"],"fm":[6,3]},{"id":"yunyang-guan-su-bie","t":"云阳馆与韩绅宿别","d":"唐","a":"司空曙","f":"诗","pn":"云阳馆","rg":"陕西 · 咸阳","lat":34.53,"lng":108.84,"l":["故人江海别，","几度隔山川。","乍见翻疑梦，","相悲各问年。","孤灯寒照雨，","湿竹暗浮烟。","更有明朝恨，","离杯惜共传。"],"g":["赠别","羁旅","感慨"],"fm":[2,3]},{"id":"song-li-zhongcheng","t":"送李中丞归汉阳别业","d":"唐","a":"刘长卿","f":"诗","pn":"汉阳","rg":"湖北 · 武汉","lat":30.55,"lng":114.28,"l":["流落征南将，","曾驱十万师。","罢归无旧业，","老去恋明时。","独立三边静，","轻生一剑知。","茫茫江汉上，","日暮欲何之。"],"g":["赠别","感遇","言志"],"fm":[6,2]},{"id":"chu-ye-shi-tou-yi","t":"除夜宿石头驿","d":"唐","a":"戴叔伦","f":"诗","pn":"石头驿","rg":"江西 · 南昌","lat":28.68,"lng":115.86,"l":["旅馆谁相问，","寒灯独可亲。","一年将尽夜，","万里未归人。","寥落悲前事，","支离笑此身。","愁颜与衰鬓，","明日又逢春。"],"g":["羁旅","思乡","节令"],"fm":[2,3]},{"id":"guo-shan-nong-jia","t":"过山农家","d":"唐","a":"顾况","f":"诗","pn":"顾渚山","rg":"浙江 · 湖州","lat":31.05,"lng":119.75,"l":["板桥人渡泉声，","茅檐日午鸡鸣。","莫嗔焙茶烟暗，","却喜晒谷天晴。"],"g":["田园","民生","写景"],"fm":[0,2]},{"id":"shi-hao-li","t":"石壕吏","d":"唐","a":"杜甫","f":"诗","pn":"石壕村","rg":"河南 · 三门峡","lat":34.73,"lng":111.6,"l":["暮投石壕村，","有吏夜捉人。","老翁逾墙走，","老妇出门看。","吏呼一何怒，","妇啼一何苦。","听妇前致词，","三男邺城戍。","一男附书至，","二男新战死。","存者且偷生，","死者长已矣。","室中更无人，","惟有乳下孙。","有孙母未去，","出入无完裙。","老妪力虽衰，","请从吏夜归。","急应河阳役，","犹得备晨炊。","夜久语声绝，","如闻泣幽咽。","天明登前途，","独与老翁别。"],"g":["民生","战争","讽喻"],"fm":[0,4]},{"id":"yong-huai-gu-ji-san","t":"咏怀古迹·其三","d":"唐","a":"杜甫","f":"诗","pn":"昭君村","rg":"湖北 · 宜昌","lat":31.22,"lng":110.75,"l":["群山万壑赴荆门，","生长明妃尚有村。","一去紫台连朔漠，","独留青冢向黄昏。","画图省识春风面，","环佩空归月夜魂。","千载琵琶作胡语，","分明怨恨曲中论。"],"g":["怀古","咏史","愁思"],"fm":[2,3]},{"id":"guan-yi-mai","t":"观刈麦","d":"唐","a":"白居易","f":"诗","pn":"盩厔县衙","rg":"陕西 · 西安","lat":34.16,"lng":108.21,"l":["田家少闲月，","五月人倍忙。","夜来南风起，","小麦覆陇黄。","妇姑荷箪食，","童稚携壶浆。","相随饷田去，","丁壮在南冈。","足蒸暑土气，","背灼炎天光。","力尽不知热，","但惜夏日长。","复有贫妇人，","抱子在其旁。","右手秉遗穗，","左臂悬敝筐。","听其相顾言，","闻者为悲伤。","家田输税尽，","拾此充饥肠。","今我何功德，","曾不事农桑。","吏禄三百石，","岁晏有余粮。","念此私自愧，","尽日不能忘。"],"g":["民生","讽喻","感遇"],"fm":[8,3]},{"id":"wen-le-tian-shou-jiangzhou","t":"闻乐天授江州司马","d":"唐","a":"元稹","f":"诗","pn":"通州衙斋","rg":"四川 · 达州","lat":31.21,"lng":107.5,"l":["残灯无焰影幢幢，","此夕闻君谪九江。","垂死病中惊坐起，","暗风吹雨入寒窗。"],"g":["酬赠","感遇","友情"],"fm":[2,4]},{"id":"xun-lu-hongjian-bu-yu","t":"寻陆鸿渐不遇","d":"唐","a":"皎然","f":"诗","pn":"苕溪","rg":"浙江 · 湖州","lat":30.87,"lng":120.09,"l":["移家虽带郭，","野径入桑麻。","近种篱边菊，","秋来未著花。","扣门无犬吠，","欲去问西家。","报道山中去，","归时每日斜。"],"g":["隐逸","访隐","写景"],"fm":[0,2]},{"id":"zuo-qian-lan-guan","t":"左迁至蓝关示侄孙湘","d":"唐","a":"韩愈","f":"诗","pn":"蓝关","rg":"陕西 · 西安","lat":34,"lng":109.55,"l":["一封朝奏九重天，","夕贬潮州路八千。","欲为圣明除弊事，","肯将衰朽惜残年。","云横秦岭家何在，","雪拥蓝关马不前。","知汝远来应有意，","好收吾骨瘴江边。"],"g":["感遇","言志","羁旅"],"fm":[4,4]},{"id":"nan-yuan-shi-san","t":"南园十三首·其五","d":"唐","a":"李贺","f":"诗","pn":"昌谷","rg":"河南 · 洛阳","lat":34.55,"lng":111.75,"l":["男儿何不带吴钩，","收取关山五十州。","请君暂上凌烟阁，","若个书生万户侯。"],"g":["言志","爱国","感遇"],"fm":[0,4]},{"id":"shan-zhong-wen-da","t":"山中问答","d":"唐","a":"李白","f":"诗","pn":"白兆山","rg":"湖北 · 孝感","lat":31.3,"lng":113.58,"l":["问余何意栖碧山，","笑而不答心自闲。","桃花流水窅然去，","别有天地非人间。"],"g":["隐逸","山水","闲适"],"fm":[2,4]},{"id":"ye-su-qipan-ling","t":"夜宿七盘岭","d":"唐","a":"沈佺期","f":"诗","pn":"七盘岭","rg":"四川 · 广元","lat":32.72,"lng":105.95,"l":["独游千里外，","高卧七盘西。","晓月临窗近，","天河入户低。","芳春平仲绿，","清夜子规啼。","浮客空留听，","褒城闻曙鸡。"],"g":["羁旅","写景","思乡"],"fm":[2,2]},{"id":"long-xi-xing","t":"陇西行","d":"唐","a":"陈陶","f":"诗","pn":"无定河","rg":"陕西 · 榆林","lat":38.28,"lng":109.73,"l":["誓扫匈奴不顾身，","五千貂锦丧胡尘。","可怜无定河边骨，","犹是春闺梦里人。"],"g":["战争","相思","边塞"],"fm":[2,4]},{"id":"chun-yuan-jinchangxu","t":"春怨","d":"唐","a":"金昌绪","f":"诗","pn":"辽西","rg":"辽宁 · 朝阳","lat":41.57,"lng":120.45,"l":["打起黄莺儿，","莫教枝上啼。","啼时惊妾梦，","不得到辽西。"],"g":["相思","战争","愁思"],"fm":[0,3]},{"id":"yong-e","t":"咏鹅","d":"唐","a":"骆宾王","f":"诗","pn":"骆宾王故里","rg":"浙江 · 金华","lat":29.31,"lng":120.07,"l":["鹅，鹅，鹅，","曲项向天歌。","白毛浮绿水，","红掌拨清波。"],"g":["咏物","童趣","写景"],"fm":[2,5]},{"id":"zheng-ren-yuan","t":"征人怨","d":"唐","a":"柳中庸","f":"诗","pn":"青冢","rg":"内蒙古 · 呼和浩特","lat":40.71,"lng":111.68,"l":["岁岁金河复玉关，","朝朝马策与刀环。","三春白雪归青冢，","万里黄河绕黑山。"],"g":["边塞","战争","愁思"],"fm":[2,2]},{"id":"she-ri","t":"社日","d":"唐","a":"王驾","f":"诗","pn":"鹅湖山","rg":"江西 · 上饶","lat":28.24,"lng":117.75,"l":["鹅湖山下稻粱肥，","豚栅鸡栖半掩扉。","桑柘影斜春社散，","家家扶得醉人归。"],"g":["田园","节令","写景"],"fm":[2,3]},{"id":"su-wusong-shan","t":"宿五松山下荀媪家","d":"唐","a":"李白","f":"诗","pn":"五松山","rg":"安徽 · 铜陵","lat":30.94,"lng":117.82,"l":["我宿五松下，","寂寥无所欢。","田家秋作苦，","邻女夜舂寒。","跪进雕胡饭，","月光明素盘。","令人惭漂母，","三谢不能餐。"],"g":["民生","感遇","田园"],"fm":[4,2]},{"id":"feng-luo-yin","t":"蜂","d":"唐","a":"罗隐","f":"诗","pn":"新城","rg":"浙江 · 杭州","lat":30.03,"lng":119.72,"l":["不论平地与山尖，","无限风光尽被占。","采得百花成蜜后，","为谁辛苦为谁甜。"],"g":["咏物","讽喻","感遇"],"fm":[2,4]},{"id":"jiang-jin-jiu","t":"将进酒","d":"唐","a":"李白","f":"诗","pn":"嵩山","rg":"河南 · 郑州","lat":34.5,"lng":113.02,"l":["君不见，","黄河之水天上来，","奔流到海不复回。","君不见，","高堂明镜悲白发，","朝如青丝暮成雪。","人生得意须尽欢，","莫使金樽空对月。","天生我材必有用，","千金散尽还复来。","烹羊宰牛且为乐，","会须一饮三百杯。","岑夫子，","丹丘生，","将进酒，","杯莫停。","与君歌一曲，","请君为我倾耳听。","钟鼓馔玉不足贵，","但愿长醉不复醒。","古来圣贤皆寂寞，","惟有饮者留其名。","陈王昔时宴平乐，","斗酒十千恣欢谑。","主人何为言少钱，","径须沽取对君酌。","五花马，","千金裘，","呼儿将出换美酒，","与尔同销万古愁。"],"g":["豪放","愁思","言志"],"fm":[8,5.5]},{"id":"yue-xia-du-zhuo","t":"月下独酌·其一","d":"唐","a":"李白","f":"诗","pn":"长安","rg":"陕西 · 西安","lat":34.27,"lng":108.95,"l":["花间一壶酒，","独酌无相亲。","举杯邀明月，","对影成三人。","月既不解饮，","影徒随我身。","暂伴月将影，","行乐须及春。","我歌月徘徊，","我舞影零乱。","醒时同交欢，","醉后各分散。","永结无情游，","相期邈云汉。"],"g":["月夜","孤傲","旷达"],"fm":[2,5]},{"id":"emei-shan-yue-ge","t":"峨眉山月歌","d":"唐","a":"李白","f":"诗","pn":"峨眉山","rg":"四川 · 乐山","lat":29.52,"lng":103.33,"l":["峨眉山月半轮秋，","影入平羌江水流。","夜发清溪向三峡，","思君不见下渝州。"],"g":["山水","思乡","行旅"],"fm":[0,4]},{"id":"ke-zhong-zuo","t":"客中作","d":"唐","a":"李白","f":"诗","pn":"兰陵","rg":"山东 · 临沂兰陵","lat":34.86,"lng":118.07,"l":["兰陵美酒郁金香，","玉碗盛来琥珀光。","但使主人能醉客，","不知何处是他乡。"],"g":["羁旅","旷达","思乡"],"fm":[2,3]},{"id":"shu-dao-nan","t":"蜀道难","d":"唐","a":"李白","f":"诗","pn":"剑门关","rg":"四川 · 广元剑阁","lat":32.35,"lng":105.55,"l":["噫吁嚱，","危乎高哉！","蜀道之难，","难于上青天！","蚕丛及鱼凫，","开国何茫然！","尔来四万八千岁，","不与秦塞通人烟。","西当太白有鸟道，","可以横绝峨眉巅。","地崩山摧壮士死，","然后天梯石栈相钩连。","上有六龙回日之高标，","下有冲波逆折之回川。","黄鹤之飞尚不得过，","猿猱欲度愁攀援。","青泥何盘盘，","百步九折萦岩峦。","扪参历井仰胁息，","以手抚膺坐长叹。","问君西游何时还？","畏途巉岩不可攀。","但见悲鸟号古木，","雄飞雌从绕林间。","又闻子规啼夜月，","愁空山。","蜀道之难，","难于上青天，","使人听此凋朱颜！","连峰去天不盈尺，","枯松倒挂倚绝壁。","飞湍瀑流争喧豗，","砯崖转石万壑雷。","其险也如此，","嗟尔远道之人胡为乎来哉！","剑阁峥嵘而崔嵬，","一夫当关，","万夫莫开。","所守或匪亲，","化为狼与豺。","朝避猛虎，","夕避长蛇，","磨牙吮血，","杀人如麻。","锦城虽云乐，","不如早还家。","蜀道之难，","难于上青天，","侧身西望长咨嗟！"],"g":["山水","行旅","豪放"],"fm":[2,5.5]},{"id":"chun-ye-luocheng-wen-di","t":"春夜洛城闻笛","d":"唐","a":"李白","f":"诗","pn":"洛阳","rg":"河南 · 洛阳","lat":34.62,"lng":112.45,"l":["谁家玉笛暗飞声，","散入春风满洛城。","此夜曲中闻折柳，","何人不起故园情。"],"g":["思乡","音乐","月夜"],"fm":[2,4]},{"id":"deng-tai-bai-feng","t":"登太白峰","d":"唐","a":"李白","f":"诗","pn":"太白山","rg":"陕西 · 宝鸡眉县","lat":34.05,"lng":107.76,"l":["西上太白峰，","夕阳穷登攀。","太白与我语，","为我开天关。","愿乘泠风去，","直出浮云间。","举手可近月，","前行若无山。","一别武功去，","何时复更还？"],"g":["登临","山水","隐逸"],"fm":[6,2]},{"id":"wen-wang-changling","t":"闻王昌龄左迁龙标遥有此寄","d":"唐","a":"李白","f":"诗","pn":"龙标","rg":"湖南 · 怀化洪江","lat":27.11,"lng":110,"l":["杨花落尽子规啼，","闻道龙标过五溪。","我寄愁心与明月，","随君直到夜郎西。"],"g":["赠别","怀人","月夜"],"fm":[2,4]},{"id":"fang-dai-tian-shan-dao-shi","t":"访戴天山道士不遇","d":"唐","a":"李白","f":"诗","pn":"戴天山","rg":"四川 · 绵阳江油","lat":31.92,"lng":104.75,"l":["犬吠水声中，","桃花带露浓。","树深时见鹿，","溪午不闻钟。","野竹分青霭，","飞泉挂碧峰。","无人知所去，","愁倚两三松。"],"g":["访隐","山水","写景"],"fm":[2,3]},{"id":"su-tai-lan-gu","t":"苏台览古","d":"唐","a":"李白","f":"诗","pn":"姑苏台","rg":"江苏 · 苏州","lat":31.26,"lng":120.53,"l":["旧苑荒台杨柳新，","菱歌清唱不胜春。","只今惟有西江月，","曾照吴王宫里人。"],"g":["怀古","咏史","写景"],"fm":[2,3]},{"id":"yue-zhong-lan-gu","t":"越中览古","d":"唐","a":"李白","f":"诗","pn":"越王台","rg":"浙江 · 绍兴","lat":29.99,"lng":120.57,"l":["越王勾践破吴归，","战士还家尽锦衣。","宫女如花满春殿，","只今惟有鹧鸪飞。"],"g":["怀古","咏史","感慨"],"fm":[2,3]},{"id":"nan-ling-bie-er-tong","t":"南陵别儿童入京","d":"唐","a":"李白","f":"诗","pn":"南陵","rg":"安徽 · 芜湖","lat":30.92,"lng":118.34,"l":["白酒新熟山中归，","黄鸡啄黍秋正肥。","呼童烹鸡酌白酒，","儿女嬉笑牵人衣。","高歌取醉欲自慰，","起舞落日争光辉。","游说万乘苦不早，","著鞭跨马涉远道。","会稽愚妇轻买臣，","余亦辞家西入秦。","仰天大笑出门去，","我辈岂是蓬蒿人。"],"g":["言志","豪情","亲情"],"fm":[10,5]},{"id":"sha-qiu-cheng-xia-ji-dufu","t":"沙丘城下寄杜甫","d":"唐","a":"李白","f":"诗","pn":"沙丘","rg":"山东 · 济宁兖州","lat":35.55,"lng":116.83,"l":["我来竟何事，","高卧沙丘城。","城边有古树，","日夕连秋声。","鲁酒不可醉，","齐歌空复情。","思君若汶水，","浩荡寄南征。"],"g":["友情","怀人"],"fm":[6,2]},{"id":"chang-gan-xing","t":"长干行·其一","d":"唐","a":"李白","f":"诗","pn":"长干里","rg":"江苏 · 南京","lat":32.01,"lng":118.78,"l":["妾发初覆额，","折花门前剧。","郎骑竹马来，","绕床弄青梅。","同居长干里，","两小无嫌猜。","十四为君妇，","羞颜未尝开。","低头向暗壁，","千唤不一回。","十五始展眉，","愿同尘与灰。","常存抱柱信，","岂上望夫台。","十六君远行，","瞿塘滟滪堆。","五月不可触，","猿声天上哀。","门前迟行迹，","一一生绿苔。","苔深不能扫，","落叶秋风早。","八月蝴蝶来，","双飞西园草。","感此伤妾心，","坐愁红颜老。","早晚下三巴，","预将书报家。","相迎不道远，","直至长风沙。"],"g":["爱情","相思","民歌"],"fm":[2,5]},{"id":"heng-jiang-ci","t":"横江词·其一","d":"唐","a":"李白","f":"诗","pn":"横江浦","rg":"安徽 · 马鞍山和县","lat":31.72,"lng":118.4,"l":["人道横江好，","侬道横江恶。","一风三日吹倒山，","白浪高于瓦官阁。"],"g":["山水","写景","豪情"],"fm":[2,2]},{"id":"yi-qin-e","t":"忆秦娥·箫声咽","d":"唐","a":"李白","f":"词","pn":"咸阳","rg":"陕西 · 咸阳","lat":34.33,"lng":108.71,"l":["箫声咽，","秦娥梦断秦楼月。","秦楼月，","年年柳色，","灞陵伤别。","乐游原上清秋节，","咸阳古道音尘绝。","音尘绝，","西风残照，","汉家陵阙。"],"g":["怀古","愁思","相思"],"fm":[8,4]},{"id":"deng-guang-wu-gu-zhan-chang","t":"登广武古战场怀古","d":"唐","a":"李白","f":"诗","pn":"广武","rg":"河南 · 郑州荥阳","lat":34.88,"lng":113.38,"l":["秦鹿奔野草，","逐之若飞蓬。","项王气盖世，","紫电明双瞳。","呼吸八千人，","横行起江东。","赤精斩白帝，","叱咤入关中。","两龙不并跃，","五纬与天同。","楚灭无英图，","汉兴有成功。","按剑清八极，","归酣歌大风。","伊昔临广武，","连兵决雌雄。","分我一杯羹，","太皇乃汝翁。","战争有古迹，","壁垒颓层穹。","猛虎啸洞壑，","饥鹰鸣秋空。","翔云列晓阵，","杀气赫长虹。","拨乱属豪圣，","俗儒安可通。","沉湎呼竖子，","狂言非至公。","抚掌黄河曲，","嗤嗤阮嗣宗。"],"g":["怀古","咏史","战争"],"fm":[2,1]},{"id":"ye-su-shan-si","t":"夜宿山寺","d":"唐","a":"李白","f":"诗","pn":"蔡山","rg":"湖北 · 黄冈黄梅","lat":29.83,"lng":115.94,"l":["危楼高百尺，","手可摘星辰。","不敢高声语，","恐惊天上人。"],"g":["登临","禅意"],"fm":[0,5]},{"id":"shan-zhong-yu-you-ren-dui-zhuo","t":"山中与幽人对酌","d":"唐","a":"李白","f":"诗","pn":"徂徕山","rg":"山东 · 泰安","lat":36.02,"lng":117.32,"l":["两人对酌山花开，","一杯一杯复一杯。","我醉欲眠卿且去，","明朝有意抱琴来。"],"g":["隐逸","闲适","友情"],"fm":[0,3]},{"id":"guan-shan-yue","t":"关山月","d":"唐","a":"李白","f":"诗","pn":"天山","rg":"新疆 · 乌鲁木齐","lat":43.83,"lng":87.62,"l":["明月出天山，","苍茫云海间。","长风几万里，","吹度玉门关。","汉下白登道，","胡窥青海湾。","由来征战地，","不见有人还。","戍客望边色，","思归多苦颜。","高楼当此夜，","叹息未应闲。"],"g":["边塞","思乡","战争"],"fm":[0,4]},{"id":"ci-tongguan","t":"次潼关先寄张十二阁老使君","d":"唐","a":"韩愈","f":"诗","pn":"潼关","rg":"陕西 · 渭南","lat":34.55,"lng":110.25,"l":["荆山已去华山来，","日照潼关四扇开。","刺史莫辞迎候远，","相公新破蔡州回。"],"g":["战争","豪情","言志"],"fm":[0,2]},{"id":"ti-mu-ju-shi","t":"题木居士","d":"唐","a":"韩愈","f":"诗","pn":"衡山","rg":"湖南 · 衡阳","lat":27.25,"lng":112.85,"l":["火透波穿不计春，","根如头面干如身。","偶然题作木居士，","便有无穷求福人。"],"g":["咏物","讽喻","哲理"],"fm":[2,2]},{"id":"chun-xue","t":"春雪","d":"唐","a":"韩愈","f":"诗","pn":"长安","rg":"陕西 · 西安","lat":34.27,"lng":108.95,"l":["新年都未有芳华，","二月初惊见草芽。","白雪却嫌春色晚，","故穿庭树作飞花。"],"g":["写景","咏物","节令"],"fm":[2,3]},{"id":"xiang-zhong","t":"湘中","d":"唐","a":"韩愈","f":"诗","pn":"汨罗江","rg":"湖南 · 岳阳","lat":28.8,"lng":113.05,"l":["猿愁鱼踊水翻波，","自古流传是汨罗。","蘋藻满盘无处奠，","空闻渔父扣舷歌。"],"g":["怀古","感遇","愁思"],"fm":[0,2]},{"id":"deng-liuzhou-chenglou","t":"登柳州城楼寄漳汀封连四州","d":"唐","a":"柳宗元","f":"诗","pn":"柳州","rg":"广西 · 柳州","lat":24.32,"lng":109.42,"l":["城上高楼接大荒，","海天愁思正茫茫。","惊风乱飐芙蓉水，","密雨斜侵薜荔墙。","岭树重遮千里目，","江流曲似九回肠。","共来百越文身地，","犹自音书滞一乡。"],"g":["登临","愁思","思乡"],"fm":[4,3]},{"id":"liuzhou-rongye","t":"柳州二月榕叶落尽偶题","d":"唐","a":"柳宗元","f":"诗","pn":"柳州","rg":"广西 · 柳州","lat":24.32,"lng":109.42,"l":["宦情羁思共凄凄，","春半如秋意转迷。","山城过雨百花尽，","榕叶满庭莺乱啼。"],"g":["羁旅","愁思","感遇"],"fm":[2,2]},{"id":"yu-weng","t":"渔翁","d":"唐","a":"柳宗元","f":"诗","pn":"永州","rg":"湖南 · 永州","lat":26.42,"lng":111.61,"l":["渔翁夜傍西岩宿，","晓汲清湘燃楚竹。","烟销日出不见人，","欸乃一声山水绿。","回看天际下中流，","岩上无心云相逐。"],"g":["山水","隐逸","写景"],"fm":[2,3]},{"id":"nanjian-zhong-ti","t":"南涧中题","d":"唐","a":"柳宗元","f":"诗","pn":"永州","rg":"湖南 · 永州","lat":26.42,"lng":111.61,"l":["秋气集南涧，","独游亭午时。","回风一萧瑟，","林影久参差。","始至若有得，","稍深遂忘疲。","羁禽响幽谷，","寒藻舞沦漪。","去国魂已远，","怀人泪空垂。","孤生易为感，","失路少所宜。","索寞竟何事，","徘徊只自知。","谁为后来者，","当与此心期。"],"g":["山水","孤傲","感遇"],"fm":[0,2]},{"id":"shui-diao-ge-tou","t":"水调歌头·明月几时有","d":"宋","a":"苏轼","f":"词","pn":"密州超然台","rg":"山东 · 潍坊诸城","lat":36,"lng":119.41,"l":["明月几时有？","把酒问青天。","不知天上宫阙，","今夕是何年。","我欲乘风归去，","又恐琼楼玉宇，","高处不胜寒。","起舞弄清影，","何似在人间。","转朱阁，","低绮户，","照无眠。","不应有恨，","何事长向别时圆？","人有悲欢离合，","月有阴晴圆缺，","此事古难全。","但愿人长久，","千里共婵娟。"],"pr":"丙辰中秋，欢饮达旦，大醉，作此篇，兼怀子由。","g":["怀人","节令","哲理"],"fm":[17,5.5]},{"id":"nian-nu-jiao","t":"念奴娇·赤壁怀古","d":"宋","a":"苏轼","f":"词","pn":"黄州赤壁","rg":"湖北 · 黄冈","lat":30.45,"lng":114.88,"l":["大江东去，","浪淘尽，","千古风流人物。","故垒西边，","人道是，","三国周郎赤壁。","乱石穿空，","惊涛拍岸，","卷起千堆雪。","江山如画，","一时多少豪杰。","遥想公瑾当年，","小乔初嫁了，","雄姿英发。","羽扇纶巾，","谈笑间，","樯橹灰飞烟灭。","故国神游，","多情应笑我，","早生华发。","人生如梦，","一尊还酹江月。"],"g":["怀古","咏史"],"fm":[0,5.5,3]},{"id":"ding-feng-bo","t":"定风波·莫听穿林打叶声","d":"宋","a":"苏轼","f":"词","pn":"黄州沙湖","rg":"湖北 · 黄冈","lat":30.42,"lng":114.95,"l":["莫听穿林打叶声，","何妨吟啸且徐行。","竹杖芒鞋轻胜马，","谁怕？","一蓑烟雨任平生。","料峭春风吹酒醒，","微冷，","山头斜照却相迎。","回首向来萧瑟处，","归去，","也无风雨也无晴。"],"pr":"三月七日，沙湖道中遇雨，雨具先去，同行皆狼狈，余独不觉。已而遂晴，故作此。","g":["言志","旷达"],"fm":[2,5,3]},{"id":"jiangcheng-ji-meng","t":"江城子·乙卯正月二十日夜记梦","d":"宋","a":"苏轼","f":"词","pn":"密州","rg":"山东 · 潍坊诸城","lat":35.99,"lng":119.4,"l":["十年生死两茫茫，","不思量，","自难忘。","千里孤坟，","无处话凄凉。","纵使相逢应不识，","尘满面，","鬓如霜。","夜来幽梦忽还乡，","小轩窗，","正梳妆。","相顾无言，","惟有泪千行。","料得年年肠断处，","明月夜，","短松冈。"],"g":["悼亡","爱情"],"fm":[0,5,3]},{"id":"wang-jiangnan","t":"望江南·超然台作","d":"宋","a":"苏轼","f":"词","pn":"密州超然台","rg":"山东 · 潍坊诸城","lat":36,"lng":119.41,"l":["春未老，","风细柳斜斜。","试上超然台上看，","半壕春水一城花。","烟雨暗千家。","寒食后，","酒醒却咨嗟。","休对故人思故国，","且将新火试新茶。","诗酒趁年华。"],"g":["节令","思乡"],"fm":[8,4]},{"id":"linjiang-xian","t":"临江仙·夜归临皋","d":"宋","a":"苏轼","f":"词","pn":"黄州临皋亭","rg":"湖北 · 黄冈","lat":30.45,"lng":114.88,"l":["夜饮东坡醒复醉，","归来仿佛三更。","家童鼻息已雷鸣。","敲门都不应，","倚杖听江声。","长恨此身非我有，","何时忘却营营。","夜阑风静縠纹平。","小舟从此逝，","江海寄余生。"],"g":["隐逸","旷达"],"fm":[8,4]},{"id":"ti-xi-lin-bi","t":"题西林壁","d":"宋","a":"苏轼","f":"诗","pn":"庐山西林寺","rg":"江西 · 九江","lat":29.56,"lng":115.97,"l":["横看成岭侧成峰，","远近高低各不同。","不识庐山真面目，","只缘身在此山中。"],"g":["哲理","山水"],"fm":[2,5.5]},{"id":"yin-hu-shang","t":"饮湖上初晴后雨","d":"宋","a":"苏轼","f":"诗","pn":"西湖","rg":"浙江 · 杭州","lat":30.25,"lng":120.15,"l":["水光潋滟晴方好，","山色空蒙雨亦奇。","欲把西湖比西子，","淡妆浓抹总相宜。"],"g":["写景","咏物"],"fm":[2,5.5]},{"id":"wanghu-lou","t":"六月二十七日望湖楼醉书","d":"宋","a":"苏轼","f":"诗","pn":"望湖楼","rg":"浙江 · 杭州","lat":30.26,"lng":120.15,"l":["黑云翻墨未遮山，","白雨跳珠乱入船。","卷地风来忽吹散，","望湖楼下水如天。"],"g":["写景","雨景"],"fm":[0,4]},{"id":"huan-xi-sha-qingquan","t":"浣溪沙·游蕲水清泉寺","d":"宋","a":"苏轼","f":"词","pn":"蕲水清泉寺","rg":"湖北 · 黄冈浠水","lat":30.45,"lng":115.25,"l":["山下兰芽短浸溪，","松间沙路净无泥，","萧萧暮雨子规啼。","谁道人生无再少？","门前流水尚能西！","休将白发唱黄鸡。"],"pr":"游蕲水清泉寺，寺临兰溪，溪水西流。","g":["哲理","言志"],"fm":[3,4]},{"id":"gui-zhi-xiang","t":"桂枝香·金陵怀古","d":"宋","a":"王安石","f":"词","pn":"金陵","rg":"江苏 · 南京","lat":32.04,"lng":118.78,"l":["登临送目，","正故国晚秋，","天气初肃。","千里澄江似练，","翠峰如簇。","归帆去棹残阳里，","背西风，","酒旗斜矗。","彩舟云淡，","星河鹭起，","画图难足。","念往昔，","繁华竞逐，","叹门外楼头，","悲恨相续。","千古凭高对此，","谩嗟荣辱。","六朝旧事随流水，","但寒烟衰草凝绿。","至今商女，","时时犹唱，","后庭遗曲。"],"g":["怀古","咏史"],"fm":[17,3]},{"id":"bo-chuan-gua-zhou","t":"泊船瓜洲","d":"宋","a":"王安石","f":"诗","pn":"瓜洲","rg":"江苏 · 扬州","lat":32.25,"lng":119.4,"l":["京口瓜洲一水间，","钟山只隔数重山。","春风又绿江南岸，","明月何时照我还。"],"g":["思乡","行旅"],"fm":[2,5.5]},{"id":"deng-fei-lai-feng","t":"登飞来峰","d":"宋","a":"王安石","f":"诗","pn":"飞来峰","rg":"浙江 · 杭州","lat":30.24,"lng":120.09,"l":["飞来山上千寻塔，","闻说鸡鸣见日升。","不畏浮云遮望眼，","自缘身在最高层。"],"g":["登临","言志"],"fm":[2,5]},{"id":"yuan-ri","t":"元日","d":"宋","a":"王安石","f":"诗","pn":"江宁钟山","rg":"江苏 · 南京","lat":32.06,"lng":118.85,"l":["爆竹声中一岁除，","春风送暖入屠苏。","千门万户曈曈日，","总把新桃换旧符。"],"g":["节令","言志"],"fm":[0,5]},{"id":"yu-jia-ao","t":"渔家傲·秋思","d":"宋","a":"范仲淹","f":"词","pn":"延州","rg":"陕西 · 延安","lat":36.6,"lng":109.49,"l":["塞下秋来风景异，","衡阳雁去无留意。","四面边声连角起，","千嶂里，","长烟落日孤城闭。","浊酒一杯家万里，","燕然未勒归无计。","羌管悠悠霜满地，","人不寐，","将军白发征夫泪。"],"g":["边塞","思乡"],"fm":[5,4]},{"id":"cai-sang-zi","t":"采桑子·群芳过后西湖好","d":"宋","a":"欧阳修","f":"词","pn":"颍州西湖","rg":"安徽 · 阜阳","lat":32.9,"lng":115.8,"l":["群芳过后西湖好，","狼籍残红，","飞絮濛濛，","垂柳阑干尽日风。","笙歌散尽游人去，","始觉春空，","垂下帘栊，","双燕归来细雨中。"],"g":["写景","惜春"],"fm":[0,3,3]},{"id":"chao-zhong-ze","t":"朝中措·平山堂","d":"宋","a":"欧阳修","f":"词","pn":"平山堂","rg":"江苏 · 扬州","lat":32.42,"lng":119.38,"l":["平山阑槛倚晴空，","山色有无中。","手种堂前垂柳，","别来几度春风。","文章太守，","挥毫万字，","一饮千钟。","行乐直须年少，","尊前看取衰翁。"],"g":["怀旧","酬赠"],"fm":[0,3]},{"id":"yu-lin-ling","t":"雨霖铃·寒蝉凄切","d":"宋","a":"柳永","f":"词","pn":"汴京","rg":"河南 · 开封","lat":34.8,"lng":114.3,"l":["寒蝉凄切，","对长亭晚，","骤雨初歇。","都门帐饮无绪，","留恋处，","兰舟催发。","执手相看泪眼，","竟无语凝噎。","念去去，","千里烟波，","暮霭沉沉楚天阔。","多情自古伤离别，","更那堪，","冷落清秋节！","今宵酒醒何处？","杨柳岸，","晓风残月。","此去经年，","应是良辰好景虚设。","便纵有千种风情，","更与何人说？"],"g":["赠别","爱情"],"fm":[14,5.5,3]},{"id":"wang-hai-chao","t":"望海潮·东南形胜","d":"宋","a":"柳永","f":"词","pn":"杭州","rg":"浙江 · 杭州","lat":30.25,"lng":120.15,"l":["东南形胜，","三吴都会，","钱塘自古繁华。","烟柳画桥，","风帘翠幕，","参差十万人家。","云树绕堤沙，","怒涛卷霜雪，","天堑无涯。","市列珠玑，","户盈罗绮，","竞豪奢。","重湖叠巘清嘉，","有三秋桂子，","十里荷花。","羌管弄晴，","菱歌泛夜，","嬉嬉钓叟莲娃。","千骑拥高牙，","乘醉听箫鼓，","吟赏烟霞。","异日图将好景，","归去凤池夸。"],"g":["写景","都市"],"fm":[13,4]},{"id":"huan-xi-sha-yanshu","t":"浣溪沙·一曲新词酒一杯","d":"宋","a":"晏殊","f":"词","pn":"汴京","rg":"河南 · 开封","lat":34.8,"lng":114.3,"l":["一曲新词酒一杯，","去年天气旧亭台。","夕阳西下几时回？","无可奈何花落去，","似曾相识燕归来。","小园香径独徘徊。"],"g":["惜时","哲理"],"fm":[3,5]},{"id":"yi-jian-mei","t":"一剪梅·红藕香残玉簟秋","d":"宋","a":"李清照","f":"词","pn":"青州归来堂","rg":"山东 · 潍坊青州","lat":36.7,"lng":118.5,"l":["红藕香残玉簟秋。","轻解罗裳，","独上兰舟。","云中谁寄锦书来，","雁字回时，","月满西楼。","花自飘零水自流。","一种相思，","两处闲愁。","此情无计可消除，","才下眉头，","却上心头。"],"g":["相思","爱情"],"fm":[9,5,3]},{"id":"ru-meng-ling-xiting","t":"如梦令·常记溪亭日暮","d":"宋","a":"李清照","f":"词","pn":"溪亭","rg":"山东 · 济南","lat":36.65,"lng":117.12,"l":["常记溪亭日暮，","沉醉不知归路。","兴尽晚回舟，","误入藕花深处。","争渡，","争渡，","惊起一滩鸥鹭。"],"g":["童趣","写景"],"fm":[3,5,4]},{"id":"ru-meng-ling-fengzhou","t":"如梦令·昨夜雨疏风骤","d":"宋","a":"李清照","f":"词","pn":"青州","rg":"山东 · 潍坊青州","lat":36.7,"lng":118.5,"l":["昨夜雨疏风骤，","浓睡不消残酒。","试问卷帘人，","却道海棠依旧。","知否，","知否？","应是绿肥红瘦。"],"g":["惜春","咏物"],"fm":[4,5,3]},{"id":"zui-hua-yin","t":"醉花阴·薄雾浓云愁永昼","d":"宋","a":"李清照","f":"词","pn":"莱州","rg":"山东 · 烟台莱州","lat":37.18,"lng":120.38,"l":["薄雾浓云愁永昼，","瑞脑销金兽。","佳节又重阳，","玉枕纱厨，","半夜凉初透。","东篱把酒黄昏后，","有暗香盈袖。","莫道不销魂，","帘卷西风，","人比黄花瘦。"],"g":["相思","节令"],"fm":[7,5,3]},{"id":"sheng-sheng-man","t":"声声慢·寻寻觅觅","d":"宋","a":"李清照","f":"词","pn":"临安","rg":"浙江 · 杭州","lat":30.25,"lng":120.15,"l":["寻寻觅觅，","冷冷清清，","凄凄惨惨戚戚。","乍暖还寒时候，","最难将息。","三杯两盏淡酒，","怎敌他、","晚来风急！","雁过也，","正伤心，","却是旧时相识。","满地黄花堆积，","憔悴损，","如今有谁堪摘？","守着窗儿，","独自怎生得黑！","梧桐更兼细雨，","到黄昏、","点点滴滴。","这次第，","怎一个愁字了得！"],"g":["悲秋","愁思"],"fm":[0,5.5,3]},{"id":"wu-ling-chun","t":"武陵春·风住尘香花已尽","d":"宋","a":"李清照","f":"词","pn":"金华","rg":"浙江 · 金华","lat":29.08,"lng":119.65,"l":["风住尘香花已尽，","日晚倦梳头。","物是人非事事休，","欲语泪先流。","闻说双溪春尚好，","也拟泛轻舟。","只恐双溪舴艋舟，","载不动许多愁。"],"g":["愁思","漂泊"],"fm":[2,5]},{"id":"yong-yu-le","t":"永遇乐·京口北固亭怀古","d":"宋","a":"辛弃疾","f":"词","pn":"北固亭","rg":"江苏 · 镇江","lat":32.25,"lng":119.47,"l":["千古江山，","英雄无觅孙仲谋处。","舞榭歌台，","风流总被雨打风吹去。","斜阳草树，","寻常巷陌，","人道寄奴曾住。","想当年，","金戈铁马，","气吞万里如虎。","元嘉草草，","封狼居胥，","赢得仓皇北顾。","四十三年，","望中犹记，","烽火扬州路。","可堪回首，","佛狸祠下，","一片神鸦社鼓。","凭谁问：","廉颇老矣，","尚能饭否？"],"g":["怀古","爱国"],"fm":[19,5,3]},{"id":"qing-yu-an","t":"青玉案·元夕","d":"宋","a":"辛弃疾","f":"词","pn":"临安元夕","rg":"浙江 · 杭州","lat":30.25,"lng":120.15,"l":["东风夜放花千树，","更吹落、","星如雨。","宝马雕车香满路。","凤箫声动，","玉壶光转，","一夜鱼龙舞。","蛾儿雪柳黄金缕，","笑语盈盈暗香去。","众里寻他千百度，","蓦然回首，","那人却在，","灯火阑珊处。"],"g":["节令","爱情"],"fm":[9,5.5,4]},{"id":"xi-jiang-yue","t":"西江月·夜行黄沙道中","d":"宋","a":"辛弃疾","f":"词","pn":"黄沙岭","rg":"江西 · 上饶","lat":28.45,"lng":117.95,"l":["明月别枝惊鹊，","清风半夜鸣蝉。","稻花香里说丰年，","听取蛙声一片。","七八个星天外，","两三点雨山前。","旧时茅店社林边，","路转溪桥忽见。"],"g":["田园","写景"],"fm":[2,5]},{"id":"qing-ping-le","t":"清平乐·村居","d":"宋","a":"辛弃疾","f":"词","pn":"上饶带湖","rg":"江西 · 上饶","lat":28.45,"lng":117.95,"l":["茅檐低小，","溪上青青草。","醉里吴音相媚好，","白发谁家翁媪？","大儿锄豆溪东，","中儿正织鸡笼。","最喜小儿亡赖，","溪头卧剥莲蓬。"],"g":["田园","童趣"],"fm":[6,4]},{"id":"po-zhen-zi","t":"破阵子·为陈同甫赋壮词以寄之","d":"宋","a":"辛弃疾","f":"词","pn":"上饶","rg":"江西 · 上饶","lat":28.45,"lng":117.95,"l":["醉里挑灯看剑，","梦回吹角连营。","八百里分麾下炙，","五十弦翻塞外声，","沙场秋点兵。","马作的卢飞快，","弓如霹雳弦惊。","了却君王天下事，","赢得生前身后名。","可怜白发生！"],"g":["爱国","言志"],"fm":[0,5]},{"id":"chou-nu-er","t":"丑奴儿·书博山道中壁","d":"宋","a":"辛弃疾","f":"词","pn":"博山道中","rg":"江西 · 上饶广丰","lat":28.45,"lng":118.15,"l":["少年不识愁滋味，","爱上层楼。","爱上层楼，","为赋新词强说愁。","而今识尽愁滋味，","欲说还休。","欲说还休，","却道天凉好个秋。"],"g":["愁思","感慨"],"fm":[0,5,4]},{"id":"shui-long-yin","t":"水龙吟·登建康赏心亭","d":"宋","a":"辛弃疾","f":"词","pn":"赏心亭","rg":"江苏 · 南京","lat":32.01,"lng":118.78,"l":["楚天千里清秋，","水随天去秋无际。","遥岑远目，","献愁供恨，","玉簪螺髻。","落日楼头，","断鸿声里，","江南游子。","把吴钩看了，","栏杆拍遍，","无人会，","登临意。","休说鲈鱼堪脍，","尽西风、","季鹰归未？","求田问舍，","怕应羞见，","刘郎才气。","可惜流年，","忧愁风雨，","树犹如此！","倩何人唤取，","红巾翠袖，","揾英雄泪？"],"g":["登临","言志"],"fm":[8,4,4]},{"id":"man-jiang-hong","t":"满江红·写怀","d":"宋","a":"岳飞","f":"词","pn":"鄂州","rg":"湖北 · 武汉","lat":30.59,"lng":114.3,"l":["怒发冲冠，","凭栏处、","潇潇雨歇。","抬望眼，","仰天长啸，","壮怀激烈。","三十功名尘与土，","八千里路云和月。","莫等闲、","白了少年头，","空悲切。","靖康耻，","犹未雪。","臣子恨，","何时灭！","驾长车，","踏破贺兰山缺。","壮志饥餐胡虏肉，","笑谈渴饮匈奴血。","待从头、","收拾旧山河，","朝天阙。"],"g":["爱国","言志"],"fm":[6,5.5]},{"id":"guo-ling-ding-yang","t":"过零丁洋","d":"宋","a":"文天祥","f":"诗","pn":"零丁洋","rg":"广东 · 珠江口","lat":22.4,"lng":113.8,"l":["辛苦遭逢起一经，","干戈寥落四周星。","山河破碎风飘絮，","身世浮沉雨打萍。","惶恐滩头说惶恐，","零丁洋里叹零丁。","人生自古谁无死？","留取丹心照汗青。"],"g":["爱国","言志"],"fm":[6,5.5]},{"id":"ti-lin-an-di","t":"题临安邸","d":"宋","a":"林升","f":"诗","pn":"临安客店","rg":"浙江 · 杭州","lat":30.25,"lng":120.15,"l":["山外青山楼外楼，","西湖歌舞几时休？","暖风熏得游人醉，","直把杭州作汴州。"],"g":["讽喻","忧国"],"fm":[0,5]},{"id":"you-shan-xi-cun","t":"游山西村","d":"宋","a":"陆游","f":"诗","pn":"镜湖三山","rg":"浙江 · 绍兴","lat":30,"lng":120.58,"l":["莫笑农家腊酒浑，","丰年留客足鸡豚。","山重水复疑无路，","柳暗花明又一村。","箫鼓追随春社近，","衣冠简朴古风存。","从今若许闲乘月，","拄杖无时夜叩门。"],"g":["田园","哲理"],"fm":[2,5]},{"id":"chai-tou-feng","t":"钗头凤·红酥手","d":"宋","a":"陆游","f":"词","pn":"沈园","rg":"浙江 · 绍兴","lat":30,"lng":120.6,"l":["红酥手，","黄縢酒，","满城春色宫墙柳。","东风恶，","欢情薄。","一怀愁绪，","几年离索。","错、错、错。","春如旧，","人空瘦，","泪痕红浥鲛绡透。","桃花落，","闲池阁。","山盟虽在，","锦书难托。","莫、莫、莫！"],"g":["爱情","伤情"],"fm":[0,5,3]},{"id":"su-zhong-qing","t":"诉衷情·当年万里觅封侯","d":"宋","a":"陆游","f":"词","pn":"山阴","rg":"浙江 · 绍兴","lat":30,"lng":120.58,"l":["当年万里觅封侯，","匹马戍梁州。","关河梦断何处？","尘暗旧貂裘。","胡未灭，","鬓先秋，","泪空流。","此生谁料，","心在天山，","老沧洲。"],"g":["爱国","言志"],"fm":[7,4,3]},{"id":"shi-yi-yue","t":"十一月四日风雨大作","d":"宋","a":"陆游","f":"诗","pn":"山阴孤村","rg":"浙江 · 绍兴","lat":30,"lng":120.58,"l":["僵卧孤村不自哀，","尚思为国戍轮台。","夜阑卧听风吹雨，","铁马冰河入梦来。"],"g":["爱国","言志"],"fm":[2,5]},{"id":"lin-an-chun-yu","t":"临安春雨初霁","d":"宋","a":"陆游","f":"诗","pn":"临安客寓","rg":"浙江 · 杭州","lat":30.25,"lng":120.15,"l":["世味年来薄似纱，","谁令骑马客京华。","小楼一夜听春雨，","深巷明朝卖杏花。","矮纸斜行闲作草，","晴窗细乳戏分茶。","素衣莫起风尘叹，","犹及清明可到家。"],"g":["羁旅","愁思"],"fm":[2,5]},{"id":"jianmen-dao-zhong","t":"剑门道中遇微雨","d":"宋","a":"陆游","f":"诗","pn":"剑门关","rg":"四川 · 广元剑阁","lat":32.35,"lng":105.55,"l":["衣上征尘杂酒痕，","远游无处不销魂。","此身合是诗人未？","细雨骑驴入剑门。"],"g":["行旅","自嘲"],"fm":[2,4]},{"id":"xiao-chu-jing-ci","t":"晓出净慈寺送林子方","d":"宋","a":"杨万里","f":"诗","pn":"净慈寺","rg":"浙江 · 杭州","lat":30.24,"lng":120.15,"l":["毕竟西湖六月中，","风光不与四时同。","接天莲叶无穷碧，","映日荷花别样红。"],"g":["写景","赠别"],"fm":[2,5.5]},{"id":"xiao-chi","t":"小池","d":"宋","a":"杨万里","f":"诗","pn":"吉水","rg":"江西 · 吉安","lat":27.22,"lng":115.13,"l":["泉眼无声惜细流，","树阴照水爱晴柔。","小荷才露尖尖角，","早有蜻蜓立上头。"],"g":["写景","童趣"],"fm":[2,5]},{"id":"su-xin-shi","t":"宿新市徐公店","d":"宋","a":"杨万里","f":"诗","pn":"新市","rg":"浙江 · 湖州德清","lat":30.55,"lng":120.13,"l":["篱落疏疏一径深，","树头新绿未成阴。","儿童急走追黄蝶，","飞入菜花无处寻。"],"g":["田园","童趣"],"fm":[2,4]},{"id":"guan-shu-you-gan","t":"观书有感","d":"宋","a":"朱熹","f":"诗","pn":"建阳考亭","rg":"福建 · 南平建阳","lat":27.35,"lng":117.65,"l":["半亩方塘一鉴开，","天光云影共徘徊。","问渠那得清如许？","为有源头活水来。"],"g":["哲理","读书"],"fm":[2,5]},{"id":"deng-kuai-ge","t":"登快阁","d":"宋","a":"黄庭坚","f":"诗","pn":"快阁","rg":"江西 · 吉安泰和","lat":26.8,"lng":114.9,"l":["痴儿了却公家事，","快阁东西倚晚晴。","落木千山天远大，","澄江一道月分明。","朱弦已为佳人绝，","青眼聊因美酒横。","万里归船弄长笛，","此心吾与白鸥盟。"],"g":["登临","言志"],"fm":[2,3]},{"id":"si-shi-tian-yuan","t":"四时田园杂兴（其二）","d":"宋","a":"范成大","f":"诗","pn":"苏州石湖","rg":"江苏 · 苏州","lat":31.28,"lng":120.56,"l":["梅子金黄杏子肥，","麦花雪白菜花稀。","日长篱落无人过，","惟有蜻蜓蛱蝶飞。"],"g":["田园","写景"],"fm":[0,4]},{"id":"shan-yuan-xiao-mei","t":"山园小梅","d":"宋","a":"林逋","f":"诗","pn":"西湖孤山","rg":"浙江 · 杭州","lat":30.26,"lng":120.15,"l":["众芳摇落独暄妍，","占尽风情向小园。","疏影横斜水清浅，","暗香浮动月黄昏。","霜禽欲下先偷眼，","粉蝶如知合断魂。","幸有微吟可相狎，","不须檀板共金樽。"],"g":["咏物","隐逸"],"fm":[2,5]},{"id":"qing-yu-an-hengtang","t":"青玉案·凌波不过横塘路","d":"宋","a":"贺铸","f":"词","pn":"横塘","rg":"江苏 · 苏州","lat":31.28,"lng":120.55,"l":["凌波不过横塘路，","但目送、","芳尘去。","锦瑟华年谁与度？","月桥花院，","琐窗朱户，","只有春知处。","飞云冉冉蘅皋暮，","彩笔新题断肠句。","试问闲愁都几许？","一川烟草，","满城风絮，","梅子黄时雨。"],"g":["相思","愁思"],"fm":[9,4,4]},{"id":"su-mu-zhe","t":"苏幕遮·燎沉香","d":"宋","a":"周邦彦","f":"词","pn":"汴京","rg":"河南 · 开封","lat":34.8,"lng":114.3,"l":["燎沉香，","消溽暑。","鸟雀呼晴，","侵晓窥檐语。","叶上初阳干宿雨，","水面清圆，","一一风荷举。","故乡遥，","何日去？","家住吴门，","久作长安旅。","五月渔郎相忆否？","小楫轻舟，","梦入芙蓉浦。"],"g":["思乡","咏物"],"fm":[4,4,3]},{"id":"yangzhou-man","t":"扬州慢·淮左名都","d":"宋","a":"姜夔","f":"词","pn":"扬州","rg":"江苏 · 扬州","lat":32.39,"lng":119.42,"l":["淮左名都，","竹西佳处，","解鞍少驻初程。","过春风十里，","尽荠麦青青。","自胡马窥江去后，","废池乔木，","犹厌言兵。","渐黄昏，","清角吹寒，","都在空城。","杜郎俊赏，","算而今重到须惊。","纵豆蔻词工，","青楼梦好，","难赋深情。","二十四桥仍在，","波心荡，","冷月无声。","念桥边红药，","年年知为谁生？"],"pr":"淳熙丙申至日，予过维扬。夜雪初霁，荠麦弥望。入其城，则四顾萧条，寒水自碧，暮色渐起，戍角悲吟。予怀怆然，感慨今昔，因自度此曲。千岩老人以为有《黍离》之悲也。","g":["怀古","伤今"],"fm":[16,4,3]},{"id":"yu-mei-ren","t":"虞美人·听雨","d":"宋","a":"蒋捷","f":"词","pn":"宜兴","rg":"江苏 · 无锡宜兴","lat":31.36,"lng":119.82,"l":["少年听雨歌楼上，","红烛昏罗帐。","壮年听雨客舟中，","江阔云低、","断雁叫西风。","而今听雨僧庐下，","鬓已星星也。","悲欢离合总无情，","一任阶前、","点滴到天明。"],"g":["感慨","人生"],"fm":[0,4]},{"id":"chai-tou-feng-tangwan","t":"钗头凤·世情薄","d":"宋","a":"唐婉","f":"词","pn":"沈园","rg":"浙江 · 绍兴","lat":30,"lng":120.6,"l":["世情薄，","人情恶，","雨送黄昏花易落。","晓风干，","泪痕残，","欲笺心事，","独语斜阑。","难，难，难！","人成各，","今非昨，","病魂常似秋千索。","角声寒，","夜阑珊，","怕人寻问，","咽泪装欢。","瞒，瞒，瞒！"],"g":["爱情","伤情"],"fm":[0,3,3]},{"id":"yue-ke","t":"约客","d":"宋","a":"赵师秀","f":"诗","pn":"永嘉","rg":"浙江 · 温州","lat":28,"lng":120.65,"l":["黄梅时节家家雨，","青草池塘处处蛙。","有约不来过夜半，","闲敲棋子落灯花。"],"g":["闲适","写景"],"fm":[2,4]},{"id":"san-qu-dao-zhong","t":"三衢道中","d":"宋","a":"曾几","f":"诗","pn":"三衢","rg":"浙江 · 衢州","lat":28.93,"lng":118.87,"l":["梅子黄时日日晴，","小溪泛尽却山行。","绿阴不减来时路，","添得黄鹂四五声。"],"g":["写景","行旅"],"fm":[0,3]},{"id":"xiangyi-dao-zhong","t":"襄邑道中","d":"宋","a":"陈与义","f":"诗","pn":"襄邑","rg":"河南 · 商丘睢县","lat":34.45,"lng":115,"l":["飞花两岸照船红，","百里榆堤半日风。","卧看满天云不动，","不知云与我俱东。"],"g":["行旅","写景"],"fm":[2,3]},{"id":"linjiang-xian-xiaogui","t":"临江仙·梦后楼台高锁","d":"宋","a":"晏几道","f":"词","pn":"汴京","rg":"河南 · 开封","lat":34.8,"lng":114.3,"l":["梦后楼台高锁，","酒醒帘幕低垂。","去年春恨却来时。","落花人独立，","微雨燕双飞。","记得小蘋初见，","两重心字罗衣。","琵琶弦上说相思。","当时明月在，","曾照彩云归。"],"g":["怀人","相思"],"fm":[3,4]},{"id":"xiangcun-siyue","t":"乡村四月","d":"宋","a":"翁卷","f":"诗","pn":"永嘉乡间","rg":"浙江 · 温州","lat":28,"lng":120.65,"l":["绿遍山原白满川，","子规声里雨如烟。","乡村四月闲人少，","才了蚕桑又插田。"],"g":["田园","民生"],"fm":[2,4]},{"id":"jiangcheng-chulie","t":"江城子·密州出猎","d":"宋","a":"苏轼","f":"词","pn":"常山","rg":"山东 · 潍坊诸城","lat":35.99,"lng":119.41,"l":["老夫聊发少年狂，","左牵黄，右擎苍，","锦帽貂裘，千骑卷平冈。","为报倾城随太守，","亲射虎，看孙郎。","酒酣胸胆尚开张。","鬓微霜，又何妨！","持节云中，何日遣冯唐？","会挽雕弓如满月，","西北望，射天狼。"],"g":["豪情","爱国"],"fm":[8,5]},{"id":"bu-suan-zi","t":"卜算子·黄州定慧院寓居作","d":"宋","a":"苏轼","f":"词","pn":"定慧院","rg":"湖北 · 黄冈","lat":30.45,"lng":114.88,"l":["缺月挂疏桐，","漏断人初静。","谁见幽人独往来，","缥缈孤鸿影。","惊起却回头，","有恨无人省。","拣尽寒枝不肯栖，","寂寞沙洲冷。"],"g":["咏物","言志"],"fm":[6,4]},{"id":"xi-jiang-yue-dameng","t":"西江月·世事一场大梦","d":"宋","a":"苏轼","f":"词","pn":"黄州临皋亭","rg":"湖北 · 黄冈","lat":30.45,"lng":114.88,"l":["世事一场大梦，","人生几度秋凉。","夜来风叶已鸣廊。","看取眉头鬓上。","酒贱常愁客少，","月明多被云妨。","中秋谁与共孤光。","把盏凄然北望。"],"g":["感慨","人生"],"fm":[0,3]},{"id":"zhe-gu-tian-huangzhou","t":"鹧鸪天·林断山明竹隐墙","d":"宋","a":"苏轼","f":"词","pn":"黄州东坡","rg":"湖北 · 黄冈","lat":30.45,"lng":114.88,"l":["林断山明竹隐墙。","乱蝉衰草小池塘。","翻空白鸟时时见，","照水红蕖细细香。","村舍外，古城旁。","杖藜徐步转斜阳。","殷勤昨夜三更雨，","又得浮生一日凉。"],"g":["田园","写景"],"fm":[6,3]},{"id":"man-ting-fang-guiqu","t":"满庭芳·归去来兮","d":"宋","a":"苏轼","f":"词","pn":"黄州雪堂","rg":"湖北 · 黄冈","lat":30.45,"lng":114.88,"l":["归去来兮，","吾归何处？","万里家在岷峨。","百年强半，","来日苦无多。","坐见黄州再闰，","儿童尽、楚语吴歌。","山中友，","鸡豚社酒，","相劝老东坡。","云何。","当此际，","人生底事，","来往如梭。","待闲看秋风，","洛水清波。","好在堂前细柳，","应念我、莫剪柔柯。","仍传语，","江南父老，","时与晒渔蓑。"],"pr":"元丰七年四月一日，余将去黄移汝，留别雪堂邻里二三君子，会李仲览自江东来别，遂书以遗之。","g":["羁旅","言志"],"fm":[0,2]},{"id":"shui-long-yin-yanghua","t":"水龙吟·次韵章质夫杨花词","d":"宋","a":"苏轼","f":"词","pn":"黄州","rg":"湖北 · 黄冈","lat":30.45,"lng":114.88,"l":["似花还似非花，","也无人惜从教坠。","抛家傍路，","思量却是，","无情有思。","萦损柔肠，","困酣娇眼，","欲开还闭。","梦随风万里，","寻郎去处，","又还被、莺呼起。","不恨此花飞尽，","恨西园、落红难缀。","晓来雨过，","遗踪何在？","一池萍碎。","春色三分，","二分尘土，","一分流水。","细看来，","不是杨花，","点点是离人泪。"],"g":["咏物","相思"],"fm":[19,4,3]},{"id":"dong-xian-ge","t":"洞仙歌·冰肌玉骨","d":"宋","a":"苏轼","f":"词","pn":"黄州","rg":"湖北 · 黄冈","lat":30.45,"lng":114.88,"l":["冰肌玉骨，","自清凉无汗。","水殿风来暗香满。","绣帘开，","一点明月窥人，","人未寝，","欹枕钗横鬓乱。","起来携素手，","庭户无声，","时见疏星渡河汉。","试问夜如何？","夜已三更，","金波淡，","玉绳低转。","但屈指西风几时来，","又不道流年暗中偷换。"],"pr":"仆七岁时，见眉山老尼，姓朱，忘其名，年九十余，自言尝随其师入蜀主孟昶宫中。一日大热，蜀主与花蕊夫人夜纳凉摩诃池上，作一词，朱具能记之。今四十年，朱已死久矣，人无知此词者，但记其首两句。暇日寻味，岂《洞仙歌令》乎？乃为足之云。","g":["怀古","惜时"],"fm":[14,3]},{"id":"man-jiang-hong-jie","t":"满江红·寄鄂州朱使君寿昌","d":"宋","a":"苏轼","f":"词","pn":"鄂州","rg":"湖北 · 武汉","lat":30.59,"lng":114.3,"l":["江汉西来，","高楼下、蒲萄深碧。","犹自带、岷峨云浪，","锦江春色。","君是南山遗爱守，","我为剑外思归客。","对此间、风物岂无情，","殷勤说。","江表传，君休读。","狂处士，真堪惜。","空洲对鹦鹉，","苇花萧瑟。","不独笑书生争底事，","曹公黄祖俱飘忽。","愿使君、还赋谪仙诗，","追黄鹤。"],"g":["怀古","登临"],"fm":[0,2]},{"id":"nan-xiang-zi-chongjiu","t":"南乡子·重九涵辉楼呈徐君猷","d":"宋","a":"苏轼","f":"词","pn":"涵辉楼","rg":"湖北 · 黄冈","lat":30.45,"lng":114.88,"l":["霜降水痕收。","浅碧鳞鳞露远洲。","酒力渐消风力软，","飕飕。","破帽多情却恋头。","佳节若为酬。","但把清尊断送秋。","万事到头都是梦，","休休。","明日黄花蝶也愁。"],"g":["节令","感慨"],"fm":[7,3,3]},{"id":"shui-diao-kuaizai","t":"水调歌头·黄州快哉亭赠张偓佺","d":"宋","a":"苏轼","f":"词","pn":"快哉亭","rg":"湖北 · 黄冈","lat":30.45,"lng":114.88,"l":["落日绣帘卷，","亭下水连空。","知君为我新作，","窗户湿青红。","长记平山堂上，","欹枕江南烟雨，","杳杳没孤鸿。","认得醉翁语，","山色有无中。","一千顷，都镜净，","倒碧峰。","忽然浪起，","掀舞一叶白头翁。","堪笑兰台公子，","未解庄生天籁，","刚道有雌雄。","一点浩然气，","千里快哉风。"],"g":["登临","言志"],"fm":[16,4]},{"id":"nian-nu-jiao-zhongqiu","t":"念奴娇·中秋","d":"宋","a":"苏轼","f":"词","pn":"黄州","rg":"湖北 · 黄冈","lat":30.45,"lng":114.88,"l":["凭高眺远，","见长空万里，","云无留迹。","桂魄飞来光射处，","冷浸一天秋碧。","玉宇琼楼，","乘鸾来去，","人在清凉国。","江山如画，","望中烟树历历。","我醉拍手狂歌，","举杯邀月，","对影成三客。","起舞徘徊风露下，","今夕不知何夕。","便欲乘风，","翻然归去，","何用骑鹏翼。","水晶宫里，","一声吹断横笛。"],"g":["节令","月夜"],"fm":[11,2]},{"id":"ding-feng-bo-yunniang","t":"定风波·南海归赠王定国侍人寓娘","d":"宋","a":"苏轼","f":"词","pn":"黄州","rg":"湖北 · 黄冈","lat":30.45,"lng":114.88,"l":["常羡人间琢玉郎，","天应乞与点酥娘。","尽道清歌传皓齿，","风起，","雪飞炎海变清凉。","万里归来颜愈少，","微笑，","笑时犹带岭梅香。","试问岭南应不好，","却道：此心安处是吾乡。"],"pr":"王定国歌儿曰柔奴，姓宇文氏，眉目娟丽，善应对，家世住京师。定国南迁归，余问柔奴：「广南风土，应是不好？」柔奴对曰：「此心安处，便是吾乡。」因为缀词云。","g":["酬赠","言志"],"fm":[8,5]},{"id":"huan-xi-sha-zaohua","t":"浣溪沙·簌簌衣巾落枣花","d":"宋","a":"苏轼","f":"词","pn":"石潭","rg":"江苏 · 徐州","lat":34.27,"lng":117.18,"l":["簌簌衣巾落枣花，","村南村北响缫车。","牛衣古柳卖黄瓜。","酒困路长惟欲睡，","日高人渴漫思茶。","敲门试问野人家。"],"g":["田园","写景"],"fm":[3,3]},{"id":"yong-yu-le-pengcheng","t":"永遇乐·彭城夜宿燕子楼","d":"宋","a":"苏轼","f":"词","pn":"燕子楼","rg":"江苏 · 徐州","lat":34.27,"lng":117.2,"l":["明月如霜，","好风如水，","清景无限。","曲港跳鱼，","圆荷泻露，","寂寞无人见。","紞如三鼓，","铿然一叶，","黯黯梦云惊断。","夜茫茫，","重寻无处，","觉来小园行遍。","天涯倦客，","山中归路，","望断故园心眼。","燕子楼空，","佳人何在，","空锁楼中燕。","古今如梦，","何曾梦觉，","但有旧欢新怨。","异时对，","黄楼夜景，","为余浩叹。"],"g":["怀古","人生"],"fm":[15,3,3]},{"id":"jiangcheng-bie-xuzhou","t":"江城子·别徐州","d":"宋","a":"苏轼","f":"词","pn":"彭城","rg":"江苏 · 徐州","lat":34.27,"lng":117.18,"l":["天涯流落思无穷。","既相逢，却匆匆。","携手佳人，和泪折残红。","为问东风余几许？","春纵在，与谁同。","隋堤三月水溶溶。","背归鸿，去吴中。","回首彭城，清泗与淮通。","欲寄相思千点泪，","流不到，楚江东。"],"g":["赠别","羁旅"],"fm":[8,3]},{"id":"yang-guan-qu","t":"阳关曲·中秋作","d":"宋","a":"苏轼","f":"词","pn":"彭城","rg":"江苏 · 徐州","lat":34.27,"lng":117.18,"l":["暮云收尽溢清寒，","银汉无声转玉盘。","此生此夜不长好，","明月明年何处看。"],"g":["节令","怀人"],"fm":[2,4]},{"id":"xi-jiang-yue-pingshantang","t":"西江月·平山堂","d":"宋","a":"苏轼","f":"词","pn":"平山堂","rg":"江苏 · 扬州","lat":32.42,"lng":119.38,"l":["三过平山堂下，","半生弹指声中。","十年不见老仙翁。","壁上龙蛇飞动。","欲吊文章太守，","仍歌杨柳春风。","休言万事转头空。","未转头时皆梦。"],"g":["怀旧","感遇"],"fm":[6,3]},{"id":"shao-nian-you-runzhou","t":"少年游·润州作代人寄远","d":"宋","a":"苏轼","f":"词","pn":"润州","rg":"江苏 · 镇江","lat":32.2,"lng":119.45,"l":["去年相送，","余杭门外，","飞雪似杨花。","今年春尽，","杨花似雪，","犹不见还家。","对酒卷帘邀明月，","风露透窗纱。","恰似姮娥怜双燕，","分明照、画梁斜。"],"g":["相思","写景"],"fm":[0,3,3]},{"id":"zui-luo-po-suzhou","t":"醉落魄·苏州阊门留别","d":"宋","a":"苏轼","f":"词","pn":"阊门","rg":"江苏 · 苏州","lat":31.3,"lng":120.58,"l":["苍颜华发。","故山归计何时决。","旧交新贵音书绝。","惟有佳人，","犹作殷勤别。","离亭欲去歌声咽。","潇潇细雨凉吹颊。","泪珠不用罗巾裛。","弹在罗衫，","图得见时说。"],"g":["赠别","伤情"],"fm":[0,2]},{"id":"yu-mei-ren-youmeitang","t":"虞美人·有美堂赠述古","d":"宋","a":"苏轼","f":"词","pn":"有美堂","rg":"浙江 · 杭州","lat":30.25,"lng":120.15,"l":["湖山信是东南美，","一望弥千里。","使君能得几回来？","便使樽前醉倒、更徘徊。","沙河塘里灯初上，","水调谁家唱？","夜阑风静欲归时，","惟有一江明月、碧琉璃。"],"g":["赠别","写景"],"fm":[0,2]},{"id":"ba-sheng-ganzhou","t":"八声甘州·寄参寥子","d":"宋","a":"苏轼","f":"词","pn":"杭州","rg":"浙江 · 杭州","lat":30.25,"lng":120.15,"l":["有情风、万里卷潮来，","无情送潮归。","问钱塘江上，","西兴浦口，","几度斜晖。","不用思量今古，","俯仰昔人非。","谁似东坡老，","白首忘机。","记取西湖西畔，","正暮山好处，","空翠烟霏。","算诗人相得，","如我与君稀。","约他年、东还海道，","愿谢公、雅志莫相违。","西州路，","不应回首，","为我沾衣。"],"g":["酬赠","言志"],"fm":[0,3]},{"id":"linjiang-xian-songqian","t":"临江仙·送钱穆父","d":"宋","a":"苏轼","f":"词","pn":"杭州","rg":"浙江 · 杭州","lat":30.25,"lng":120.15,"l":["一别都门三改火，","天涯踏尽红尘。","依然一笑作春温。","无波真古井，","有节是秋筠。","惆怅孤帆连夜发，","送行淡月微云。","尊前不用翠眉颦。","人生如逆旅，","我亦是行人。"],"g":["赠别","人生"],"fm":[8,5]},{"id":"mu-lan-hua-ling","t":"木兰花令·次欧公西湖韵","d":"宋","a":"苏轼","f":"词","pn":"颍州西湖","rg":"安徽 · 阜阳","lat":32.9,"lng":115.8,"l":["霜余已失长淮阔，","空听潺潺清颍咽。","佳人犹唱醉翁词，","四十三年如电抹。","草头秋露流珠滑，","三五盈盈还二八。","与余同是识翁人，","惟有西湖波底月。"],"g":["怀旧","感遇"],"fm":[6,2]},{"id":"xi-jiang-yue-meihua","t":"西江月·梅花","d":"宋","a":"苏轼","f":"词","pn":"惠州","rg":"广东 · 惠州","lat":23.09,"lng":114.4,"l":["玉骨那愁瘴雾，","冰姿自有仙风。","海仙时遣探芳丛。","倒挂绿毛么凤。","素面翻嫌粉涴，","洗妆不褪唇红。","高情已逐晓云空。","不与梨花同梦。"],"g":["咏物","悼亡"],"fm":[0,2]},{"id":"huan-xi-sha-duanwu","t":"浣溪沙·端午","d":"宋","a":"苏轼","f":"词","pn":"惠州","rg":"广东 · 惠州","lat":23.09,"lng":114.4,"l":["轻汗微微透碧纨，","明朝端午浴芳兰。","流香涨腻满晴川。","彩线轻缠红玉臂，","小符斜挂绿云鬟。","佳人相见一千年。"],"g":["节令","写景"],"fm":[3,2]},{"id":"die-lian-hua-chunjing","t":"蝶恋花·春景","d":"宋","a":"苏轼","f":"词","pn":"惠州","rg":"广东 · 惠州","lat":23.09,"lng":114.4,"l":["花褪残红青杏小。","燕子飞时，绿水人家绕。","枝上柳绵吹又少，","天涯何处无芳草。","墙里秋千墙外道。","墙外行人，墙里佳人笑。","笑渐不闻声渐悄，","多情却被无情恼。"],"g":["写景","惜春"],"fm":[2,5]},{"id":"jian-zi-mu-lan-hua-danzhou","t":"减字木兰花·己卯儋耳春词","d":"宋","a":"苏轼","f":"词","pn":"儋州","rg":"海南 · 儋州","lat":19.52,"lng":109.58,"l":["春牛春杖，","无限春风来海上。","便丐春工，","染得桃红似肉红。","春幡春胜，","一阵春风吹酒醒。","不似天涯，","卷起杨花似雪花。"],"g":["节令","写景"],"fm":[0,2]},{"id":"ta-sha-xing-chenzhou","t":"踏莎行·郴州旅舍","d":"宋","a":"秦观","f":"词","pn":"郴州旅舍","rg":"湖南 · 郴州","lat":25.77,"lng":113.03,"l":["雾失楼台，","月迷津渡，","桃源望断无寻处。","可堪孤馆闭春寒，","杜鹃声里斜阳暮。","驿寄梅花，","鱼传尺素，","砌成此恨无重数。","郴江幸自绕郴山，","为谁流下潇湘去？"],"g":["羁旅","愁思"],"fm":[8,4]},{"id":"bu-suan-zi-wo-zhu","t":"卜算子·我住长江头","d":"宋","a":"李之仪","f":"词","pn":"当涂","rg":"安徽 · 马鞍山","lat":31.57,"lng":118.5,"l":["我住长江头，","君住长江尾。","日日思君不见君，","共饮长江水。","此水几时休，","此恨何时已。","只愿君心似我心，","定不负相思意。"],"g":["爱情","相思"],"fm":[0,5]},{"id":"zhe-gu-tian-chong-guo-chan-men","t":"鹧鸪天·重过阊门万事非","d":"宋","a":"贺铸","f":"词","pn":"阊门","rg":"江苏 · 苏州","lat":31.3,"lng":120.58,"l":["重过阊门万事非，","同来何事不同归？","梧桐半死清霜后，","头白鸳鸯失伴飞。","原上草，","露初晞，","旧栖新垅两依依。","空床卧听南窗雨，","谁复挑灯夜补衣。"],"g":["悼亡","爱情"],"fm":[7,4]},{"id":"an-xiang","t":"暗香·旧时月色","d":"宋","a":"姜夔","f":"词","pn":"苏州石湖","rg":"江苏 · 苏州","lat":31.28,"lng":120.56,"l":["旧时月色，","算几番照我，","梅边吹笛？","唤起玉人，","不管清寒与攀摘。","何逊而今渐老，","都忘却、春风词笔。","但怪得、竹外疏花，","香冷入瑶席。","江国，","正寂寂。","叹寄与路遥，","夜雪初积。","翠尊易泣，","红萼无言耿相忆。","长记曾携手处，","千树压、西湖寒碧。","又片片、吹尽也，","几时见得？"],"pr":"辛亥之冬，予载雪诣石湖。止既月，授简索句，且征新声，作此两曲。石湖把玩不已，使工妓隶习之，音节谐婉，乃名之曰《暗香》《疏影》。","g":["咏物","怀人"],"fm":[0,3,3]},{"id":"nian-nu-jiao-guo-dongting","t":"念奴娇·过洞庭","d":"宋","a":"张孝祥","f":"词","pn":"洞庭湖","rg":"湖南 · 岳阳","lat":29.25,"lng":112.75,"l":["洞庭青草，","近中秋、更无一点风色。","玉鉴琼田三万顷，","著我扁舟一叶。","素月分辉，","明河共影，","表里俱澄澈。","悠然心会，","妙处难与君说。","应念岭海经年，","孤光自照，","肝肺皆冰雪。","短发萧骚襟袖冷，","稳泛沧浪空阔。","尽挹西江，","细斟北斗，","万象为宾客。","扣舷独啸，","不知今夕何夕。"],"g":["写景","豪放"],"fm":[7,4]},{"id":"nan-xiang-zi-beiguting","t":"南乡子·登京口北固亭有怀","d":"宋","a":"辛弃疾","f":"词","pn":"北固亭","rg":"江苏 · 镇江","lat":32.25,"lng":119.47,"l":["何处望神州？","满眼风光北固楼。","千古兴亡多少事？","悠悠。","不尽长江滚滚流。","年少万兜鍪，","坐断东南战未休。","天下英雄谁敌手？","曹刘。","生子当如孙仲谋。"],"g":["怀古","爱国"],"fm":[7,5,3]},{"id":"shi-er","t":"示儿","d":"宋","a":"陆游","f":"诗","pn":"山阴","rg":"浙江 · 绍兴","lat":30,"lng":120.58,"l":["死去元知万事空，","但悲不见九州同。","王师北定中原日，","家祭无忘告乃翁。"],"g":["爱国","言志"],"fm":[2,5]},{"id":"xia-ri-jue-ju","t":"夏日绝句","d":"宋","a":"李清照","f":"诗","pn":"乌江","rg":"安徽 · 马鞍山和县","lat":31.78,"lng":118.36,"l":["生当作人杰，","死亦为鬼雄。","至今思项羽，","不肯过江东。"],"g":["爱国","咏史"],"fm":[0,5]},{"id":"hua-mei-niao","t":"画眉鸟","d":"宋","a":"欧阳修","f":"诗","pn":"滁州","rg":"安徽 · 滁州","lat":32.3,"lng":118.32,"l":["百啭千声随意移，","山花红紫树高低。","始知锁向金笼听，","不及林间自在啼。"],"g":["咏物","哲理"],"fm":[2,4]},{"id":"si-shi-tian-yuan-qi-san","t":"四时田园杂兴（其三十一）","d":"宋","a":"范成大","f":"诗","pn":"苏州石湖","rg":"江苏 · 苏州","lat":31.28,"lng":120.56,"l":["昼出耘田夜绩麻，","村庄儿女各当家。","童孙未解供耕织，","也傍桑阴学种瓜。"],"g":["田园","童趣"],"fm":[0,4]},{"id":"zhou-guo-an-ren","t":"舟过安仁","d":"宋","a":"杨万里","f":"诗","pn":"安仁","rg":"江西 · 鹰潭余江","lat":28.2,"lng":116.82,"l":["一叶渔船两小童，","收篙停棹坐船中。","怪生无雨都张伞，","不是遮头是使风。"],"g":["童趣","写景"],"fm":[2,3]},{"id":"shi-li-zhi","t":"食荔枝（其二）","d":"宋","a":"苏轼","f":"诗","pn":"惠州","rg":"广东 · 惠州","lat":23.09,"lng":114.4,"l":["罗浮山下四时春，","卢橘杨梅次第新。","日啖荔枝三百颗，","不辞长作岭南人。"],"g":["闲适","写景"],"fm":[2,5]},{"id":"mei-hua-jueju","t":"梅花","d":"宋","a":"王安石","f":"诗","pn":"钟山","rg":"江苏 · 南京","lat":32.06,"lng":118.85,"l":["墙角数枝梅，","凌寒独自开。","遥知不是雪，","为有暗香来。"],"g":["咏物","言志"],"fm":[2,5]},{"id":"you-zhong-shan","t":"游钟山","d":"宋","a":"王安石","f":"诗","pn":"钟山","rg":"江苏 · 南京","lat":32.06,"lng":118.85,"l":["终日看山不厌山，","买山终待老山间。","山花落尽山长在，","山水空流山自闲。"],"g":["隐逸","哲理"],"fm":[2,2]},{"id":"chun-ri-ou-cheng","t":"春日","d":"宋","a":"朱熹","f":"诗","pn":"武夷精舍","rg":"福建 · 南平","lat":27.65,"lng":118.16,"l":["胜日寻芳泗水滨，","无边光景一时新。","等闲识得东风面，","万紫千红总是春。"],"g":["哲理","写景"],"fm":[2,5]},{"id":"chun-ye-wang-ling","t":"春夜","d":"宋","a":"王令","f":"诗","pn":"广陵","rg":"江苏 · 扬州","lat":32.42,"lng":119.44,"l":["三月残花落更开，","小檐日日燕飞来。","子规夜半犹啼血，","不信东风唤不回。"],"g":["咏春","言志"],"fm":[2,3]},{"id":"qing-ming-wangyucheng","t":"清明","d":"宋","a":"王禹偁","f":"诗","pn":"商州","rg":"陕西 · 商洛","lat":33.87,"lng":109.93,"l":["无花无酒过清明，","兴味萧然似野僧。","昨日邻家乞新火，","晓窗分与读书灯。"],"g":["节令","闲适"],"fm":[2,3]},{"id":"jianglou-ganhuai","t":"江楼感旧","d":"宋","a":"赵嘏","f":"诗","pn":"江楼","rg":"湖南 · 岳阳","lat":29.35,"lng":113.1,"l":["独上江楼思渺然，","月光如水水如天。","同来望月人何处？","风景依稀似去年。"],"g":["怀人","月夜"],"fm":[2,4]},{"id":"chang-e-daozhong","t":"嫦娥","d":"宋","a":"李商隐","f":"诗","pn":"桂林","rg":"广西 · 桂林","lat":25.28,"lng":110.29,"l":["云母屏风烛影深，","长河渐落晓星沉。","嫦娥应悔偷灵药，","碧海青天夜夜心。"],"g":["月夜","孤清"],"fm":[2,5]},{"id":"gu-tong","t":"孤桐","d":"宋","a":"王安石","f":"诗","pn":"汴京","rg":"河南 · 开封","lat":34.79,"lng":114.31,"l":["天质自森森，","孤高几百寻。","凌霄不屈己，","得地本虚心。"],"g":["咏物","言志"],"fm":[2,2]},{"id":"tian-xian-zi","t":"天仙子·水调数声持酒听","d":"宋","a":"张先","f":"词","pn":"嘉禾","rg":"浙江 · 嘉兴","lat":30.75,"lng":120.75,"l":["水调数声持酒听，","午醉醒来愁未醒。","送春春去几时回？","临晚镜，","伤流景，","往事后期空记省。","沙上并禽池上暝，","云破月来花弄影。","重重帘幕密遮灯，","风不定，","人初静，","明日落红应满径。"],"pr":"时为嘉禾小倅，以病眠，不赴府会。","g":["惜春","愁思","写景"],"fm":[6,4]},{"id":"mu-lan-hua-wuxing","t":"木兰花·乙卯吴兴寒食","d":"宋","a":"张先","f":"词","pn":"吴兴","rg":"浙江 · 湖州","lat":30.89,"lng":120.09,"l":["龙头舴艋吴儿竞，","笋柱秋千游女并。","芳洲拾翠暮忘归，","秀野踏青来不定。","行云去后遥山暝，","已放笙歌池院静。","中庭月色正清明，","无数杨花过无影。"],"g":["节令","写景","闲适"],"fm":[6,2]},{"id":"zhe-gu-tian-xidu","t":"鹧鸪天·西都作","d":"宋","a":"朱敦儒","f":"词","pn":"洛阳","rg":"河南 · 洛阳","lat":34.62,"lng":112.45,"l":["我是清都山水郎，","天教分付与疏狂。","曾批给雨支风券，","累上留云借月章。","诗万首，","酒千觞。","几曾着眼看侯王？","玉楼金阙慵归去，","且插梅花醉洛阳。"],"g":["言志","旷达","闲适"],"fm":[7,3]},{"id":"xi-jiang-yue-zufeng","t":"西江月·阻风山峰下","d":"宋","a":"张孝祥","f":"词","pn":"黄陵庙","rg":"湖南 · 岳阳","lat":28.72,"lng":112.88,"l":["满载一船秋色，","平铺十里湖光。","波神留我看斜阳，","放起鳞鳞细浪。","明日风回更好，","今宵露宿何妨？","水晶宫里奏霓裳，","准拟岳阳楼上。"],"g":["写景","旷达","行旅"],"fm":[0,3]},{"id":"he-xin-lang-song-hu","t":"贺新郎·送胡邦衡待制赴新州","d":"宋","a":"张元干","f":"词","pn":"福州","rg":"福建 · 福州","lat":26.08,"lng":119.3,"l":["梦绕神州路。","怅秋风、","连营画角，","故宫离黍。","底事昆仑倾砥柱，","九地黄流乱注？","聚万落千村狐兔。","天意从来高难问，","况人情老易悲难诉！","更南浦，","送君去。","凉生岸柳催残暑。","耿斜河、","疏星淡月，","断云微度。","万里江山知何处？","回首对床夜语。","雁不到、","书成谁与？","目尽青天怀今古，","肯儿曹恩怨相尔汝？","举大白，","听金缕。"],"g":["赠别","爱国","忧国"],"fm":[7,3]},{"id":"bu-suan-zi-yanrui","t":"卜算子·不是爱风尘","d":"宋","a":"严蕊","f":"词","pn":"台州","rg":"浙江 · 台州","lat":28.66,"lng":121.42,"l":["不是爱风尘，","似被前缘误。","花落花开自有时，","总赖东君主。","去也终须去，","住也如何住！","若得山花插满头，","莫问奴归处。"],"g":["咏物","言志"],"fm":[6,3]},{"id":"qin-yuan-chun-chaoyang","t":"沁园春·题潮阳张许二公庙","d":"宋","a":"文天祥","f":"词","pn":"潮阳","rg":"广东 · 汕头","lat":23.26,"lng":116.6,"l":["为子死孝，","为臣死忠，","死又何妨。","自光岳气分，","士无全节；","君臣义缺，","谁负刚肠。","骂贼张巡，","爱君许远，","留取声名万古香。","后来者，","无二公之操，","百炼之钢。","人生翕欻云亡。","好烈烈轰轰做一场。","使当时卖国，","甘心降虏，","受人唾骂，","安得留芳？","古庙幽沉，","遗容俨雅，","枯木寒鸦几夕阳。","邮亭下，","有奸雄过此，","仔细思量。"],"g":["爱国","咏史","言志"],"fm":[13,2]},{"id":"man-ting-fang-wuxiangshan","t":"满庭芳·夏日溧水无想山作","d":"宋","a":"周邦彦","f":"词","pn":"无想山","rg":"江苏 · 南京溧水","lat":31.6,"lng":119.05,"l":["风老莺雏，","雨肥梅子，","午阴嘉树清圆。","地卑山近，","衣润费炉烟。","人静乌鸢自乐，","小桥外、","新绿溅溅。","凭阑久，","黄芦苦竹，","拟泛九江船。","年年，","如社燕，","飘流瀚海，","来寄修椽。","且莫思身外，","长近尊前。","憔悴江南倦客，","不堪听、","急管繁弦。","歌筵畔，","先安簟枕，","容我醉时眠。"],"g":["羁旅","写景","愁思"],"fm":[0,2,3]},{"id":"xing-xiang-zi-cunzhuang","t":"行香子·树绕村庄","d":"宋","a":"秦观","f":"词","pn":"高邮","rg":"江苏 · 扬州","lat":32.78,"lng":119.44,"l":["树绕村庄，","水满陂塘。","倚东风、","豪兴徜徉。","小园几许，","收尽春光。","有桃花红，","李花白，","菜花黄。","远远围墙，","隐隐茅堂。","飏青旗、","流水桥旁。","偶然乘兴，","步过东冈。","正莺儿啼，","燕儿舞，","蝶儿忙。"],"g":["田园","写景","闲适"],"fm":[6,3,3]},{"id":"yu-mei-ren-yizhou","t":"虞美人·宜州见梅作","d":"宋","a":"黄庭坚","f":"词","pn":"宜州","rg":"广西 · 河池","lat":24.5,"lng":108.65,"l":["天涯也有江南信，","梅破知春近。","夜阑风细得香迟，","不道晓来开遍向南枝。","玉台弄粉花应妒，","飘到眉心住。","平生个里愿杯深，","去国十年老尽少年心。"],"g":["咏物","羁旅","言志"],"fm":[0,2]},{"id":"yue-xia-di","t":"月下笛·万里孤云","d":"宋","a":"张炎","f":"词","pn":"甬东","rg":"浙江 · 宁波","lat":29.87,"lng":121.55,"l":["万里孤云，","清游渐远，","故人何处？","寒窗梦里，","犹记经行旧时路。","连昌约略无多柳，","第一是、","难听夜雨。","漫惊回凄悄，","相看烛影，","拥衾谁语？","张绪，","归何暮？","半零落依依，","断桥鸥鹭。","天涯倦旅，","此时心事良苦。","只愁重洒西州泪，","问杜曲人家在否？","恐翠袖、","正天寒，","犹倚梅花那树。"],"pr":"孤游万竹山中，闲门落叶，愁思黯然，因动黍离之感。时寓甬东积翠山舍。","g":["羁旅","怀旧","愁思"],"fm":[0,1,3]},{"id":"dong-xian-ge-sizhou","t":"洞仙歌·泗州中秋作","d":"宋","a":"晁补之","f":"词","pn":"泗州","rg":"江苏 · 淮安盱眙","lat":33.02,"lng":118.53,"l":["青烟幂处，","碧海飞金镜。","永夜闲阶卧桂影。","露凉时、","零乱多少寒螀，","神京远，","惟有蓝桥路近。","水晶帘不下，","云母屏开，","冷浸佳人淡脂粉。","待都将许多明，","付与金尊，","投晓共、","流霞倾尽。","更携取、","胡床上南楼，","看玉做人间，","素秋千顷。"],"g":["节令","月夜","写景"],"fm":[0,1]},{"id":"liu-shao-qing-chungan","t":"柳梢青·春感","d":"宋","a":"刘辰翁","f":"词","pn":"须溪","rg":"江西 · 吉安","lat":27.05,"lng":114.99,"l":["铁马蒙毡，","银花洒泪，","春入愁城。","笛里番腔，","街头戏鼓，","不是歌声。","那堪独坐青灯。","想故国、","高台月明。","辇下风光，","山中岁月，","海上心情。"],"g":["节令","爱国","愁思"],"fm":[0,2,3]},{"id":"yi-cong-hua-xitang","t":"一丛花·溪堂玩月作","d":"宋","a":"陈亮","f":"词","pn":"永康溪堂","rg":"浙江 · 金华永康","lat":28.89,"lng":120.03,"l":["冰轮斜辗镜天长，","江练隐寒光。","危阑醉倚人如画，","隔烟村、","何处鸣榔？","乌鹊倦栖，","鱼龙惊起，","星斗挂垂杨。","芦花千顷水微茫，","秋色满江乡。","楼台恍似游仙梦，","又疑是、","洛浦潇湘。","风露浩然，","山河影转，","今古照凄凉。"],"g":["月夜","写景","感慨"],"fm":[0,2]},{"id":"mu-lan-hua-suizhou","t":"木兰花·城上风光莺语乱","d":"宋","a":"钱惟演","f":"词","pn":"随州","rg":"湖北 · 随州","lat":31.69,"lng":113.38,"l":["城上风光莺语乱，","城下烟波春拍岸。","绿杨芳草几时休？","泪眼愁肠先已断。","情怀渐觉成衰晚，","鸾镜朱颜惊暗换。","昔年多病厌芳尊，","今日芳尊惟恐浅。"],"g":["愁思","感遇","惜春"],"fm":[0,2]},{"id":"ruan-lang-gui-poyang","t":"阮郎归·绍兴乙卯大雪行鄱阳道中","d":"宋","a":"向子諲","f":"词","pn":"鄱阳","rg":"江西 · 上饶","lat":29,"lng":116.7,"l":["江南江北雪漫漫，","遥知易水寒。","同云深处望三关，","断肠山又山。","天可老，","海能翻，","消除此恨难。","频闻遣使报平安，","几时鸾辂还？"],"g":["爱国","行旅","忧国"],"fm":[0,2]},{"id":"su-mu-zhe-qingzhou","t":"苏幕遮·碧云天","d":"宋","a":"范仲淹","f":"词","pn":"庆州","rg":"甘肃 · 庆阳","lat":35.71,"lng":107.64,"l":["碧云天，","黄叶地。","秋色连波，","波上寒烟翠。","山映斜阳天接水。","芳草无情，","更在斜阳外。","黯乡魂，","追旅思。","夜夜除非，","好梦留人睡。","明月楼高休独倚。","酒入愁肠，","化作相思泪。"],"g":["思乡","羁旅","悲秋"],"fm":[11,5,3]},{"id":"die-lian-hua-jian-ju","t":"蝶恋花·槛菊愁烟兰泣露","d":"宋","a":"晏殊","f":"词","pn":"应天书院","rg":"河南 · 商丘","lat":34.41,"lng":115.65,"l":["槛菊愁烟兰泣露，","罗幕轻寒，","燕子双飞去。","明月不谙离恨苦，","斜光到晓穿朱户。","昨夜西风凋碧树，","独上高楼，","望尽天涯路。","欲寄彩笺兼尺素，","山长水阔知何处？"],"g":["相思","愁思"],"fm":[5,5,3]},{"id":"man-ting-fang-feng-lao","t":"满庭芳·风老莺雏","d":"宋","a":"周邦彦","f":"词","pn":"溧水无想山","rg":"江苏 · 南京","lat":31.61,"lng":119.03,"l":["风老莺雏，","雨肥梅子，","午阴嘉树清圆。","地卑山近，","衣润费炉烟。","人静乌鸢自乐，","小桥外、新绿溅溅。","凭阑久，","黄芦苦竹，","拟泛九江船。","年年，","如社燕，","飘流瀚海，","来寄修椽。","且莫思身外，","长近尊前。","憔悴江南倦客，","不堪听、急管繁弦。","歌筵畔，","先安簟枕，容我醉时眠。"],"g":["羁旅","写景","愁思"],"fm":[0,2,3]},{"id":"qian-qiu-sui","t":"千秋岁·数声鶗鴂","d":"宋","a":"张先","f":"词","pn":"湖州乌程","rg":"浙江 · 湖州","lat":30.87,"lng":120.09,"l":["数声鶗鴂，","又报芳菲歇。","惜春更把残红折。","雨轻风色暴，","梅子青时节。","永丰柳，","无人尽日花飞雪。","莫把幺弦拨，","怨极弦能说。","天不老，","情难绝。","心似双丝网，","中有千千结。","夜过也，","东窗未白凝残月。"],"g":["爱情","惜春","相思"],"fm":[9,4,4]},{"id":"ta-sha-xing-hou-guan","t":"踏莎行·候馆梅残","d":"宋","a":"欧阳修","f":"词","pn":"夷陵驿站","rg":"湖北 · 宜昌","lat":30.7,"lng":111.29,"l":["候馆梅残，","溪桥柳细。","草薰风暖摇征辔。","离愁渐远渐无穷，","迢迢不断如春水。","寸寸柔肠，","盈盈粉泪。","楼高莫近危阑倚。","平芜尽处是春山，","行人更在春山外。"],"g":["赠别","羁旅","相思"],"fm":[8,4]},{"id":"dian-jiang-chun-qiu-qian","t":"点绛唇·蹴罢秋千","d":"宋","a":"李清照","f":"词","pn":"章丘明水","rg":"山东 · 济南","lat":36.72,"lng":117.53,"l":["蹴罢秋千，","起来慵整纤纤手。","露浓花瘦，","薄汗轻衣透。","见客入来，","袜刬金钗溜。","和羞走，","倚门回首，","却把青梅嗅。"],"g":["爱情","童趣"],"fm":[6,4,3]},{"id":"xi-fen-fei","t":"惜分飞·泪湿阑干花著露","d":"宋","a":"毛滂","f":"词","pn":"富阳僧舍","rg":"浙江 · 杭州","lat":30.05,"lng":119.96,"l":["泪湿阑干花著露，","愁到眉峰碧聚。","此恨平分取，","更无言语空相觑。","断雨残云无意绪，","寂寞朝朝暮暮。","今夜山深处，","断魂分付潮回去。"],"pr":"富阳僧舍代作别语","g":["赠别","爱情","相思"],"fm":[0,2]},{"id":"xing-xiang-zi-qi-li-lai","t":"行香子·过七里濑","d":"宋","a":"苏轼","f":"词","pn":"七里濑","rg":"浙江 · 杭州","lat":29.65,"lng":119.45,"l":["一叶舟轻，","双桨鸿惊。","水天清、影湛波平。","鱼翻藻鉴，","鹭点烟汀。","过沙溪急，","霜溪冷，","月溪明。","重重似画，","曲曲如屏。","算当年、虚老严陵。","君臣一梦，","今古空名。","但远山长，","云山乱，","晓山青。"],"g":["山水","怀古","哲理"],"fm":[0,2]},{"id":"pu-sa-man-zaokou","t":"菩萨蛮·郁孤台下清江水","d":"宋","a":"辛弃疾","f":"词","pn":"郁孤台","rg":"江西 · 赣州","lat":25.86,"lng":114.93,"l":["郁孤台下清江水，","中间多少行人泪。","西北望长安，","可怜无数山。","青山遮不住，","毕竟东流去。","江晚正愁余，","山深闻鹧鸪。"],"g":["爱国","登临","愁思"],"fm":[4,5]},{"id":"shui-long-yin-shuangxilou","t":"水龙吟·举头西北浮云","d":"宋","a":"辛弃疾","f":"词","pn":"双溪楼","rg":"福建 · 南平","lat":26.64,"lng":118.17,"l":["举头西北浮云，","倚天万里须长剑。","人言此地，","夜深长见，","斗牛光焰。","我觉山高，","潭空水冷，","月明星淡。","待燃犀下看，","凭栏却怕，","风雷怒，","鱼龙惨。","峡束苍江对起，","过危楼、欲飞还敛。","元龙老矣，不妨高卧，","冰壶凉簟。","千古兴亡，","百年悲笑，","一时登览。","问何人又卸，片帆沙岸，系斜阳缆。"],"g":["登临","爱国","言志"],"fm":[0,3]},{"id":"qiu-bo-mei-gaoxingting","t":"秋波媚·秋到边城角声哀","d":"宋","a":"陆游","f":"词","pn":"高兴亭","rg":"陕西 · 汉中","lat":33.07,"lng":107.02,"l":["秋到边城角声哀，","烽火照高台。","悲歌击筑，","凭高酹酒，","此兴悠哉。","多情谁似南山月，","特地暮云开。","灞桥烟柳，","曲江池馆，","应待人来。"],"g":["爱国","登临","言志"],"fm":[0,2]},{"id":"xi-jiang-yue-huanglingmiao","t":"西江月·满载一船秋色","d":"宋","a":"张孝祥","f":"词","pn":"黄陵庙","rg":"湖南 · 岳阳","lat":28.73,"lng":112.88,"l":["满载一船秋色，","平铺十里湖光。","波神留我看斜阳，","放起鳞鳞细浪。","明日风回更好，","今宵露宿何妨。","水晶宫里奏霓裳，","准拟岳阳楼上。"],"g":["写景","行旅","旷达"],"fm":[0,3]},{"id":"shui-diao-ge-tou-caishiji","t":"水调歌头·雪洗虏尘静","d":"宋","a":"张孝祥","f":"词","pn":"采石矶","rg":"安徽 · 马鞍山","lat":31.73,"lng":118.49,"l":["雪洗虏尘静，","风约楚云留。","何人为写悲壮，","吹角古城楼。","湖海平生豪气，","关塞如今风景，","剪烛看吴钩。","剩喜然犀处，","骇浪与天浮。","忆当年，","周与谢，","富春秋。","小乔初嫁，","香囊未解，","勋业故优游。","赤壁矶头落照，","肥水桥边衰草，","渺渺唤人愁。","我欲乘风去，","击楫誓中流。"],"g":["爱国","豪情","怀古"],"fm":[0,2]},{"id":"nian-nu-jiao-duojinglou","t":"念奴娇·危楼还望","d":"宋","a":"陈亮","f":"词","pn":"多景楼","rg":"江苏 · 镇江","lat":32.22,"lng":119.44,"l":["危楼还望，","叹此意、今古几人曾会。","鬼设神施，","浑认作、天限南疆北界。","一水横陈，","连岗三面，","做出争雄势。","六朝何事，","只成门户私计。","因笑王谢诸人，","登高怀远，","也学英雄涕。","凭却长江，","管不到、河洛腥膻无际。","正好长驱，","不须反顾，","寻取中流誓。","小儿破贼，","势成宁问强对。"],"g":["怀古","爱国","登临"],"fm":[0,2]},{"id":"tang-duo-ling-wuchang","t":"唐多令·芦叶满汀洲","d":"宋","a":"刘过","f":"词","pn":"安远楼","rg":"湖北 · 武汉","lat":30.55,"lng":114.31,"l":["芦叶满汀洲，","寒沙带浅流。","二十年重过南楼。","柳下系船犹未稳，","能几日，","又中秋。","黄鹤断矶头，","故人曾到否。","旧江山浑是新愁。","欲买桂花同载酒，","终不似，","少年游。"],"g":["怀旧","愁思","感慨"],"fm":[9,4,3]},{"id":"he-xin-lang-fuzhou","t":"贺新郎·梦绕神州路","d":"宋","a":"张元干","f":"词","pn":"福州","rg":"福建 · 福州","lat":26.08,"lng":119.31,"l":["梦绕神州路。","怅秋风、连营画角，","故宫离黍。","底事昆仑倾砥柱，","九地黄流乱注。","聚万落千村狐兔。","天意从来高难问，","况人情老易悲难诉。","更南浦，","送君去。","凉生岸柳催残暑。","耿斜河、疏星淡月，","断云微度。","万里江山知何处。","回首对床夜语。","雁不到、书成谁与。","目尽青天怀今古，","肯儿曹恩怨相尔汝。","举大白，","听金缕。"],"g":["赠别","爱国","忧国"],"fm":[6,3]},{"id":"qi-tian-le-chan","t":"齐天乐·一襟余恨宫魂断","d":"宋","a":"王沂孙","f":"词","pn":"宋六陵","rg":"浙江 · 绍兴","lat":29.99,"lng":120.72,"l":["一襟余恨宫魂断，","年年翠阴庭树。","乍咽凉柯，","还移暗叶，","重把离愁深诉。","西窗过雨。","怪瑶佩流空，","玉筝调柱。","镜暗妆残，","为谁娇鬓尚如许。","铜仙铅泪似洗，","叹携盘去远，","难贮零露。","病翼惊秋，","枯形阅世，","消得斜阳几度。","余音更苦。","甚独抱清高，","顿成凄楚。","谩想薰风，柳丝千万缕。"],"g":["咏物","感遇","愁思"],"fm":[0,1]},{"id":"yi-jian-mei-wujiang","t":"一剪梅·一片春愁待酒浇","d":"宋","a":"蒋捷","f":"词","pn":"秋娘渡","rg":"江苏 · 苏州","lat":31.16,"lng":120.65,"l":["一片春愁待酒浇。","江上舟摇，","楼上帘招。","秋娘渡与泰娘桥，","风又飘飘，","雨又萧萧。","何日归家洗客袍。","银字笙调，","心字香烧。","流光容易把人抛，","红了樱桃，","绿了芭蕉。"],"g":["羁旅","思乡","惜春"],"fm":[9,5,3]},{"id":"xi-da-yuan-zhen","t":"戏答元珍","d":"宋","a":"欧阳修","f":"诗","pn":"夷陵","rg":"湖北 · 宜昌","lat":30.7,"lng":111.29,"l":["春风疑不到天涯，","二月山城未见花。","残雪压枝犹有橘，","冻雷惊笋欲抽芽。","夜闻归雁生乡思，","病入新年感物华。","曾是洛阳花下客，","野芳虽晚不须嗟。"],"g":["感遇","思乡","言志"],"fm":[0,3]},{"id":"die-lian-hua-shen-shen","t":"蝶恋花·庭院深深深几许","d":"宋","a":"欧阳修","f":"词","pn":"汴京","rg":"河南 · 开封","lat":34.8,"lng":114.31,"l":["庭院深深深几许？","杨柳堆烟，","帘幕无重数。","玉勒雕鞍游冶处，","楼高不见章台路。","雨横风狂三月暮。","门掩黄昏，","无计留春住。","泪眼问花花不语，","乱红飞过秋千去。"],"g":["相思","惜春","愁思"],"fm":[8,4]},{"id":"yu-lou-chun-guizhi","t":"玉楼春·尊前拟把归期说","d":"宋","a":"欧阳修","f":"词","pn":"洛阳","rg":"河南 · 洛阳","lat":34.62,"lng":112.45,"l":["尊前拟把归期说，","未语春容先惨咽。","人生自是有情痴，","此恨不关风与月。","离歌且莫翻新阕，","一曲能教肠寸结。","直须看尽洛城花，","始共春风容易别。"],"g":["赠别","爱情","愁思"],"fm":[2,5]},{"id":"fengle-ting-youchun","t":"丰乐亭游春·其三","d":"宋","a":"欧阳修","f":"诗","pn":"丰乐亭","rg":"安徽 · 滁州","lat":32.28,"lng":118.28,"l":["红树青山日欲斜，","长郊草色绿无涯。","游人不管春将老，","来往亭前踏落花。"],"g":["写景","节令","惜春"],"fm":[2,3]},{"id":"shu-huyin-xiansheng-bi","t":"书湖阴先生壁","d":"宋","a":"王安石","f":"诗","pn":"钟山","rg":"江苏 · 南京","lat":32.07,"lng":118.83,"l":["茅檐长扫净无苔，","花木成畦手自栽。","一水护田将绿绕，","两山排闼送青来。"],"g":["写景","田园","山水"],"fm":[2,4]},{"id":"bei-bei-xing-hua","t":"北陂杏花","d":"宋","a":"王安石","f":"诗","pn":"钟山","rg":"江苏 · 南京","lat":32.07,"lng":118.83,"l":["一陂春水绕花身，","花影妖娆各占春。","纵被春风吹作雪，","绝胜南陌碾成尘。"],"g":["咏物","言志"],"fm":[2,3]},{"id":"die-ti-wujiang-ting","t":"叠题乌江亭","d":"宋","a":"王安石","f":"诗","pn":"乌江","rg":"安徽 · 马鞍山和县","lat":31.72,"lng":118.36,"l":["百战疲劳壮士哀，","中原一败势难回。","江东子弟今虽在，","肯与君王卷土来？"],"g":["怀古","咏史","言志"],"fm":[2,3]},{"id":"cheng-nan","t":"城南","d":"宋","a":"曾巩","f":"诗","pn":"福州","rg":"福建 · 福州","lat":26.08,"lng":119.3,"l":["雨过横塘水满堤，","乱山高下路东西。","一番桃李花开尽，","惟有青青草色齐。"],"g":["写景","惜春"],"fm":[2,3]},{"id":"yong-liu","t":"咏柳","d":"宋","a":"曾巩","f":"诗","pn":"南丰","rg":"江西 · 抚州南丰","lat":27.22,"lng":116.53,"l":["乱条犹未变初黄，","倚得东风势便狂。","解把飞花蒙日月，","不知天地有清霜。"],"g":["咏物","讽喻"],"fm":[2,3]},{"id":"ganlu-si-duojinglou","t":"甘露寺多景楼","d":"宋","a":"曾巩","f":"诗","pn":"多景楼","rg":"江苏 · 镇江","lat":32.22,"lng":119.47,"l":["欲收嘉景此楼中，","徙倚阑干四望通。","云乱水光浮紫翠，","天含山气入青红。","一川钟呗淮南月，","万里帆樯海外风。","老去衣衿尘土在，","只将心目羡冥鸿。"],"g":["登临","写景","言志"],"fm":[4,2]},{"id":"huai-mianchi-ji-zizhan","t":"怀渑池寄子瞻兄","d":"宋","a":"苏辙","f":"诗","pn":"渑池","rg":"河南 · 三门峡","lat":34.76,"lng":111.76,"l":["相携话别郑原上，","共道长途怕雪泥。","归骑还寻大梁陌，","行人已度古崤西。","曾为县吏民知否？","旧宿僧房壁共题。","遥想独游佳味少，","无言骓马但鸣嘶。"],"pr":"昔与子瞻应举，过宿县中寺舍，题其老僧奉闲之壁。","g":["亲情","羁旅","怀人"],"fm":[0,2]},{"id":"xiaoyao-tang-huisu","t":"逍遥堂会宿二首·其一","d":"宋","a":"苏辙","f":"诗","pn":"彭城","rg":"江苏 · 徐州","lat":34.26,"lng":117.19,"l":["逍遥堂后千寻木，","长送中宵风雨声。","误喜对床寻旧约，","不知漂泊在彭城。"],"pr":"辙幼从子瞻读书，未尝一日相舍。既仕，将宦游四方，读韦苏州诗至「安知风雨夜，复此对床眠」，恻然感之，乃相约早退，为闲居之乐。故子瞻始为凤翔幕府，留诗为别曰：「夜雨何时听萧瑟？」其后子瞻通守余杭，复移守胶西，而辙滞留于淮阳、济南，不见者七年。熙宁十年二月，始复会于澶濮之间，相从来徐留百余日。时宿于逍遥堂，追感前约，为二小诗记之。","g":["亲情","愁思","羁旅"],"fm":[2,2]},{"id":"nan-chuang","t":"南窗","d":"宋","a":"苏辙","f":"诗","pn":"汴京","rg":"河南 · 开封","lat":34.8,"lng":114.31,"l":["京师三日雪，","雪尽泥方深。","闭门谢还往，","不闻车马音。","西斋书帙乱，","南窗初日升。","展转守床榻，","欲起复不能。","开户失琼玉，","满阶松竹阴。","客从远方来，","疑我何苦心。","疏拙自当尔，","有酒聊共斟。"],"g":["写景","闲适"],"fm":[0,1]},{"id":"jiu-ri-he-hanweigong","t":"九日和韩魏公","d":"宋","a":"苏洵","f":"诗","pn":"汴京","rg":"河南 · 开封","lat":34.8,"lng":114.31,"l":["晚岁登门最不才，","萧萧华发映金罍。","不堪丞相延东阁，","闲伴诸儒老曲台。","佳节久从愁里过，","壮心偶傍醉中来。","暮归冲雨寒无睡，","自把新诗百遍开。"],"g":["节令","感遇","言志"],"fm":[4,2]},{"id":"you-jiazhou-longyan","t":"游嘉州龙岩","d":"宋","a":"苏洵","f":"诗","pn":"嘉州","rg":"四川 · 乐山","lat":29.57,"lng":103.77,"l":["系舟长堤下，","日夕事南征。","往意纷何速，","空岩幽自明。","使君怜远客，","高会有余情。","酌酒何能饮，","去乡怀独惊。","山川随望阔，","气候带霜清。","佳境日已去，","何时休远行。"],"g":["羁旅","愁思"],"fm":[8,1]},{"id":"tuci-changan","t":"途次长安上都漕傅谏议","d":"宋","a":"苏洵","f":"诗","pn":"长安","rg":"陕西 · 西安","lat":34.27,"lng":108.95,"l":["丈夫正多念，","老大不自安。","居家不能乐，","忽忽思中原。","慨然弃乡庐，","劫劫道路间。","穷山多虎狼，","行路非不难。","昔者倦奔走，","闭门事耕田。","蚕谷聊自给，","如此已十年。","缅怀当今人，","草草无复闲。","坚卧固不起，","芒背实在肩。","布衣与肉食，","幸可交口言。","默默不以告，","未可遽罪愆。","驱车入京洛，","藩镇皆达官。","长安逢傅侯，","愿得说肺肝。","贫贱吾老矣，","不复苦自叹。","富贵不足爱，","浮云过长天。","中怀邈有念，","惝恍难自论。","世俗不见信，","排斥仅得存。","昨者东入秦，","大麦黄满田。","秦民可无饥，","为君喜不眠。","禁军几千万，","仰此填其咽。","西蕃久不反，","老贼非常然。","士饱可以战，","吾宁为之先。","傅侯君在西，","天子忧东藩。","烽火尚未灭，","何策安西边。","傅侯君谓何，","明日将东辕。"],"g":["言志","忧国"],"fm":[26,1]}],"authors":{},"detail":"js/detail.js"};
